/* Mukammal Namaz — Shuru se Aakhir Tak (word by word). Data from the creator's own PDF. */
window.ZD_NAMAZ=[{"n":1,"t":"Namaz se pehle ki tayyari","b":[{"t":"p","s":"Namaz ki 6 shartein (namaz se pehle zaroori):","h":0},{"t":"p","s":"1. Jism ki paaki — wudu (ya zaroorat ho to ghusl)","h":0},{"t":"p","s":"2. Kapdon ki paaki — kapde paak hon","h":0},{"t":"p","s":"3. Jagah ki paaki — namaz ki jagah paak ho","h":0},{"t":"p","s":"4. Satr chhupana — mard naaf se ghutnon tak, aurat chehra, hatheliyan aur paon ke siwa poora jism","h":0},{"t":"p","s":"5. Qibla rukh hona — Kaaba ki taraf munh","h":0},{"t":"p","s":"6. Niyyat — dil mein iraada ke kaun si namaz padh raha hoon Namaz ka waqt hona bhi zaroori hai: Fajr, Zuhr, Asr, Maghrib, Isha.","h":0}]},{"n":2,"t":"Wudu ka tareeqa (tarteeb se)","b":[{"t":"p","s":"1. Niyyat karein aur Bismillah padhein","h":0},{"t":"p","s":"2. Dono haath kalaiyon tak 3 baar dhoyein","h":0},{"t":"p","s":"3. Kulli karein (3 baar)","h":0},{"t":"p","s":"4. Naak mein paani daal kar saaf karein (3 baar)","h":0},{"t":"p","s":"5. Poora chehra dhoyein (3 baar): peshani ke baalon se thodi tak, ek kaan se doosre kaan tak","h":0},{"t":"p","s":"6. Seedha baazu kohni samet, phir ulta baazu (3 baar)","h":0},{"t":"p","s":"7. Sar ka masah (ek baar)","h":0},{"t":"p","s":"8. Kaanon ka masah (ek baar)","h":0},{"t":"p","s":"9. Seedha paon takhnon samet, phir ulta paon (3 baar)","h":0},{"t":"d","id":"d001","ti":"Wudu se pehle","pad":"Bismillahir Rahmanir Raheem.","tar":"Allah ke naam se, jo bahut meherbaan nihayat reham wala hai.","hi":"Allah ke naam se, jo bahut meharbaan behad reham wala hai.","pg":2,"i":"d001"},{"t":"d","id":"d002","ti":"Wudu ke baad ki dua","pad":"Ash-hadu al-laa ilaaha illallaahu wahdahoo laa shareeka lah, wa ash-hadu anna Muhammadan abduhoo wa rasooluh. Allaahummaj-alnee minat-tawwaabeen, waj-alnee minal-mutatahhireen.","tar":"Main gawahi deta hoon ke Allah ke siwa koi maabood nahin, woh akela hai, uska koi shareek nahin, aur main gawahi deta hoon ke Muhammad ﷺ uske bande aur rasool hain. Aye Allah! Mujhe bahut tauba karne walon aur khoob paak rehne walon mein shamil farma.","hi":"Main gawahi deta hoon ke Allah ke siwa koi ma'bood (ibadat ke laayak) nahin, woh akela hai, uska koi shareek nahin, aur main gawahi deta hoon ke Muhammad ﷺ uske bande aur rasool hain. Ae Allah! Mujhe bahut tauba karne walon aur khoob paak rehne walon mein shaamil kar.","pg":2,"i":"d002"},{"t":"p","s":"Wudu todne wali cheezein: peshab, paakhana, hawa kharij hona, khoon ya peep bah kar nikalna, munh bhar qay, so jana (late kar ya tek laga kar), behoshi.","h":0}]},{"n":3,"t":"Masjid mein dakhil hone aur nikalne ki dua","b":[{"t":"d","id":"d003","ti":"Masjid mein dakhil hote waqt (pehle seedha paon)","pad":"Allaahummaf-tah lee abwaaba rahmatik.","tar":"Aye Allah! Mere liye apni rehmat ke darwaze khol de.","hi":"Ae Allah! Mere liye apni rehmat ke darwaze khol de.","pg":3,"i":"d003"},{"t":"d","id":"d004","ti":"Masjid se nikalte waqt (pehle ulta paon)","pad":"Allaahumma innee as-aluka min fadlik.","tar":"Aye Allah! Main tujh se tera fazl maangta hoon.","hi":"Ae Allah! Main tujh se tera fazl maangta hoon.","pg":3,"i":"d004"}]},{"n":4,"t":"Azaan aur uska jawab","b":[{"t":"p","s":"Azaan ke kalmaat:","h":0},{"t":"i","i":"t01"},{"t":"p","s":"Fajr ki azaan mein do baar yeh izafa hota hai: (As-salaatu khayrum minan-nawm: namaz neend se behtar hai). Jawab ka tareeqa: Muazzin jo kahe wohi dohraein. Hayya alas- salaah aur Hayya alal-falaah par","h":0},{"t":"p","s":"kahein: (Laa hawla wa laa quwwata illaa billaah: gunah se bachne ki taaqat aur neki ki taufeeq Allah hi ki taraf se hai).","h":0},{"t":"d","id":"d005","ti":"Azaan ke baad ki dua (durood padhne ke baad)","pad":"Allaahumma Rabba haazihid-da'watit-taammati was-salaatil-qaa'imah, aati Muhammadanil- waseelata wal-fadeelah, wab-'ashu maqaaman mahmoodanil-lazee wa'adtah.","tar":"Aye Allah! Is kaamil pukaar aur qaaim hone wali namaz ke Rab! Muhammad ﷺ ko waseela aur fazeelat ata farma aur unhein woh maqaam-e-mahmood ata farma jiska tu ne wada kiya hai.","hi":"Ae Allah! Is kaamil pukaar aur qaaim hone wali namaz ke Rab! Muhammad ﷺ ko waseela aur fazeelat ata kar aur unhein woh maqaam-e-mahmood ata kar jiska tu ne wada kiya hai.","pg":5,"i":"d005"}]},{"n":5,"t":"Namaz padhne ka mukammal tareeqa (do rakat ki misaal)","b":[{"t":"p","s":"Qadam 1: Niyyat","h":1},{"t":"p","s":"Dil mein iraada karein, jaise: Main Allah ke liye do rakat Fajr ki farz namaz padhta hoon, munh Qibla Shareef ki taraf. Zabaan se kehna zaroori nahin, dil ka iraada kaafi hai.","h":0},{"t":"d","id":"d006","ti":"Qadam 2: Takbeer-e-Tahreema","pad":"Allaahu Akbar.","tar":"Allah sab se bada hai.","hi":"Allah sab se bada hai.","pg":6,"i":"d006","in":["Dono haath kaanon tak uthayein (aurat kandhon tak) aur kahein:"]},{"t":"p","s":"Phir haath naaf ke neeche baandhein (mard: seedha haath ulte haath par; aurat: seene par). Nazar sajde ki jagah par rakhein.","h":0},{"t":"d","id":"d007","ti":"Qadam 3: Sana (sirf pehli rakat mein)","pad":"Subhaanakal-laahumma wa bihamdika, wa tabaarakasmuka, wa ta'aalaa jadduka, wa laa ilaaha ghayruk.","tar":"Aye Allah! Tu paak hai, apni hamd ke saath, tera naam barkat wala hai, teri shaan buland hai aur tere siwa koi maabood nahin.","hi":"Ae Allah! Tu paak hai, apni hamd ke saath, tera naam barkat wala hai, teri shaan buland hai aur tere siwa koi ma'bood (ibadat ke laayak) nahin.","pg":7,"i":"d007"},{"t":"d","id":"d008","ti":"Qadam 4: Ta'awwuz (sirf pehli rakat mein)","pad":"A'oozu billaahi minash-shaytaanir-rajeem.","tar":"Main shaitan-e-mardood se Allah ki panaah maangta hoon.","hi":"Main shaitan-e-mardood se Allah ki panaah maangta hoon.","pg":7,"i":"d008"},{"t":"d","id":"d009","ti":"Qadam 5: Bismillah (har rakat mein)","pad":"Bismillahir Rahmanir Raheem.","tar":"Allah ke naam se jo bahut meherbaan nihayat reham wala hai.","hi":"Allah ke naam se jo bahut meharbaan behad reham wala hai.","pg":7,"i":"d009"},{"t":"d","id":"d010","ti":"Qadam 6: Surah Al-Fatiha (har rakat mein, farz)","pad":"Alhamdu lillaahi Rabbil-'aalameen. Ar-Rahmaanir-Raheem. Maaliki yawmid-deen. Iyyaaka na'budu wa iyyaaka nasta'een. Ihdinas-siraatal-mustaqeem. Siraatal-lazeena an'amta 'alayhim, ghayril- maghdoobi 'alayhim wa lad-daaalleen. Aameen.","tar":"Saari taareefein Allah ke liye hain jo saare jahanon ka Rab hai\nNihayat meherbaan, bahut reham wala\nRoz-e-jaza ka maalik\nHum teri hi ibaadat karte hain aur tujh hi se madad maangte hain\nHamein seedha raasta dikha\nUn logon ka raasta jin par tu ne inaam kiya, na un ka jin par ghazab hua aur na gumrahon ka Aameen: Aye Allah! Qubool farma","hi":"Saari tareefein Allah ke liye hain jo saare jahanon ka Rab hai\nNihayat meharbaan, bahut reham wala\nInsaaf ke din (Qayamat) ka maalik\nHum teri hi ibadat karte hain aur tujh hi se madad maangte hain\nHumein seedha raasta dikha\nUn logon ka raasta jin par tu ne inaam kiya, na un ka jin par ghazab hua aur na gumrahon ka Aameen: Ae Allah! Qubool kar","pg":8,"i":"d010"},{"t":"d","id":"d011","ti":"Qadam 7: Koi surah milana (farz namaz ki pehli do rakaton mein)","pad":"Qul huwallaahu ahad. Allaahus-samad. Lam yalid wa lam yoolad. Wa lam yakul-lahoo kufuwan ahad.","tar":"Keh do ke Allah ek hai. Allah be-niyaaz hai. Na us ne kisi ko jana na woh jana gaya. Aur koi us ke barabar nahin.","hi":"Keh do ke Allah ek hai. Allah be-parwah hai. Na us ne kisi ko jana na woh jana gaya. Aur koi us ke barabar nahin.","pg":9,"i":"d011","in":["Fatiha ke baad Quran ki koi surah ya kam az kam teen chhoti aayaat padhein. Aasaan surtein:","Surah Al-Ikhlaas"]},{"t":"d","id":"d012","ti":"Surah Al-Kawthar","pad":"Innaa a'taynaakal-kawthar. Fasalli li-Rabbika wanhar. Inna shaani'aka huwal-abtar.","tar":"Beshak hum ne aap ko Kawthar ata ki. Pas apne Rab ke liye namaz padhein aur qurbani karein. Beshak aap ka dushman hi be-naam-o-nishaan hai.","hi":"Beshak hum ne aap ko Kawthar ata ki. Pas apne Rab ke liye namaz padhein aur qurbani karein. Beshak aap ka dushman hi be-naam-o-nishaan hai.","pg":10,"i":"d012"},{"t":"p","s":"Surah Al-Baqarah ki aakhri 2 aayaat (Ayat 285 aur 286)","h":0},{"t":"p","s":"Hadees: jo shakhs raat mein Surah Baqarah ki yeh aakhri 2 aayaat padh le, yeh us ke liye kaafi hain (Bukhari, Muslim).","h":0},{"t":"d","id":"d013","ti":"Ayat 285","pad":"Aamanar-Rasoolu bimaa unzila ilayhi mir-Rabbihi wal-mu'minoon. Kullun aamana billaahi wa malaa'ikatihi wa kutubihi wa rusulih. Laa nufarriqu bayna ahadim-mir-rusulih. Wa qaaloo sami'naa wa ata'naa. Ghufraanaka Rabbanaa wa ilaykal-maseer.","tar":"Rasool us cheez par imaan laaye jo un par un ke Rab ki taraf se utaari gayi, aur momin bhi. Sab Allah par, us ke farishton par, us ki kitaabon par aur us ke rasoolon par imaan laaye. (Woh kehte hain:) hum us ke rasoolon mein se kisi ek ke darmiyan farq nahin karte. Aur unhon ne kaha: hum ne suna aur maan liya. Aye hamare Rab! Teri bakhshish chahiye, aur tujh hi ki taraf lautna hai.","hi":"Rasool us cheez par imaan laaye jo un par un ke Rab ki taraf se utaari gayi, aur momin bhi. Sab Allah par, us ke farishton par, us ki kitaabon par aur us ke rasoolon par imaan laaye. (Woh kehte hain:) hum us ke rasoolon mein se kisi ek ke darmiyan farq nahin karte. Aur unhon ne kaha: hum ne suna aur maan liya. Ae hamare Rab! Teri maafi chahiye, aur tujh hi ki taraf lautna hai.","pg":11,"i":"d013"},{"t":"d","id":"d014","ti":"Ayat 286","pad":"Laa yukallifullaahu nafsan illaa wus'ahaa. Lahaa maa kasabat wa 'alayhaa maktasabat. Rabbanaa laa tu'aakhiznaa in naseenaa aw akhta'naa. Rabbanaa wa laa tahmil 'alaynaa isran kamaa hamaltahoo 'alal-lazeena min qablinaa. Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih. Wa'fu 'annaa waghfir lanaa warhamnaa. Anta mawlaanaa fansurnaa 'alal-qawmil-kaafireen.","tar":"Allah kisi ko us ki taaqat se zyada takleef nahin deta. Jo neki us ne kamaayi us ka faayda usi ko, aur jo burai kamaayi us ka nuqsaan usi par. Aye hamare Rab! Agar hum bhool jaayein ya chook jaayein to hum par pakad na farma. Aye hamare Rab! Hum par woh bojh na daal jo hum se pehle logon par daala tha. Aye hamare Rab! Hum par woh bojh na daal jis ki hum mein taaqat nahin. Hamein maaf kar de, hamein bakhsh de aur hum par reham farma. Tu hi hamara maula hai, pas kaafir qaum ke muqable mein hamari madad farma.","hi":"Allah kisi ko us ki taaqat se zyada takleef nahin deta. Jo neki us ne kamaayi us ka faayda usi ko, aur jo burai kamaayi us ka nuqsaan usi par. Ae hamare Rab! Agar hum bhool jaayein ya chook jaayein to hum par pakad na kar. Ae hamare Rab! Hum par woh bojh na daal jo hum se pehle logon par daala tha. Ae hamare Rab! Hum par woh bojh na daal jis ki hum mein taaqat nahin. Humein maaf kar de, humein maaf kar de aur hum par reham kar. Tu hi hamara maula hai, pas kaafir qaum ke muqable mein hamari madad kar.","pg":12,"i":"d014"},{"t":"d","id":"d015","ti":"Qadam 8: Ruku","pad":"Subhaana Rabbiyal-'Azeem.","tar":"Mera azmat wala Rab paak hai.","hi":"Mera badi shaan wala Rab paak hai.","pg":12,"i":"d015","in":["kehte hue jhukein. Haath ghutnon par, kamar seedhi, sar aur kamar barabar.","Padhein (kam az kam 3 baar):"]},{"t":"d","id":"d016","ti":"Qadam 9: Qawma (ruku se khade hona)","pad":"Sami'allaahu liman hamidah.","tar":"Allah ne us ki sun li jis ne us ki taareef ki.","hi":"Allah ne us ki sun li jis ne us ki tareef ki.","pg":13,"i":"d016","in":["Seedhe khade hote hue (imam aur akela namazi):"]},{"t":"d","id":"x017","ti":"Qawma: Rabbanaa lakal-hamd","pad":"Rabbanaa lakal-hamd (ya Rabbanaa wa lakal-hamd).","tar":"Aye hamare Rab! Teri hi liye saari taareefein hain.","hi":"Ae hamare Rab! Teri hi liye saari tareefein hain.","pg":13,"in":["Phir poori tarah khade ho kar (akela namazi aur muqtadi):","(ya)"]},{"t":"d","id":"d018","ti":"Qadam 10: Pehla sajda","pad":"Subhaana Rabbiyal-A'laa.","tar":"Mera sab se buland Rab paak hai.","hi":"Mera sab se buland Rab paak hai.","pg":13,"i":"d018","in":["kehte hue sajde mein jayein. Saat aaza zameen par: peshani aur naak, dono haath, dono ghutne, dono paon ki ungliyan. Padhein (kam az kam 3 baar):"]},{"t":"p","s":"Sajde mein apni zabaan mein bhi dua maang sakte hain (nafl mein). Hadees mein hai ke banda sajde mein apne Rab ke sab se qareeb hota hai.","h":0},{"t":"d","id":"d019","ti":"Qadam 11: Jalsa (do sajdon ke darmiyan baithna)","pad":"Rabbigh-fir lee, Rabbigh-fir lee.","tar":"Aye mere Rab! Mujhe bakhsh de, aye mere Rab! Mujhe bakhsh de.","hi":"Ae mere Rab! Mujhe maaf kar de, ae mere Rab! Mujhe maaf kar de.","pg":14,"i":"d019","in":["keh kar seedhe baithein (ulta paon bichha kar us par baithein, seedha khada rakhein). Ek","tasbeeh ki miqdaar thehrein. Nabi ﷺ se yeh dua manqool hai:"]},{"t":"d","id":"d020","ti":"Jalsa: mukammal dua","pad":"Allaahummagh-fir lee warhamnee wahdinee wa 'aafinee warzuqnee.","tar":"Aye Allah! Mujhe bakhsh de, mujh par reham farma, mujhe hidayat de, mujhe aafiyat de aur mujhe rizq ata farma.","hi":"Ae Allah! Mujhe maaf kar de, mujh par reham kar, mujhe hidayat de, mujhe aafiyat de aur mujhe rizq ata kar.","pg":14,"i":"d020","in":["Ya yeh mukammal dua:"]},{"t":"p","s":"Qadam 12: Doosra sajda","h":1},{"t":"p","s":"keh kar dobara sajda karein aur (3 baar) padhein. Yahan ek rakat mukammal hui.","h":0},{"t":"p","s":"Qadam 13: Doosri rakat","h":1},{"t":"p","s":"kehte hue seedhe khade hon (zameen par haath tek kar nahin, balke ghutnon par haath rakh kar). Ab Bismillah, Surah Al-Fatiha, aur koi surah padhein (Sana aur Ta'awwuz dobara nahin). Phir ruku, qawma, do sajde aur jalsa bilkul pehle ki tarah.","h":0},{"t":"d","id":"d021","ti":"Qadam 14: Qa'da, Tashahhud (At-Tahiyyaat)","pad":"At-tahiyyaatu lillaahi was-salawaatu wat-tayyibaat. As-salaamu 'alayka ayyuhan-nabiyyu wa rahmatullaahi wa barakaatuh. As-salaamu 'alaynaa wa 'alaa 'ibaadillaahis-saaliheen. Ash-hadu al-laa ilaaha illallaah, wa ash-hadu anna Muhammadan 'abduhoo wa rasooluh.","tar":"Tamam zabaani, badani aur maali ibaadatein Allah hi ke liye hain. Aye Nabi! Aap par salaam ho aur Allah ki rehmat aur barkatein hon. Hum par aur Allah ke nek bandon par salaam ho. Main gawahi deta hoon ke Allah ke siwa koi maabood nahin aur main gawahi deta hoon ke Muhammad ﷺ uske bande aur rasool hain.","hi":"Tamam zabaani, badani aur maali ibaadatein Allah hi ke liye hain. Ae Nabi! Aap par salaam ho aur Allah ki rehmat aur barkatein hon. Hum par aur Allah ke nek bandon par salaam ho. Main gawahi deta hoon ke Allah ke siwa koi ma'bood (ibadat ke laayak) nahin aur main gawahi deta hoon ke Muhammad ﷺ uske bande aur rasool hain.","pg":15,"i":"d021","in":["Doosri rakat ke doosre sajde ke baad baith jayein aur padhein:"]},{"t":"p","s":"( Ash-hadu al-laa ilaaha par shahadat ki ungli uthayein aur illallaah par neeche kar lein.)","h":0},{"t":"p","s":"Agar namaz do rakat se zyada ki ho (3 ya 4 rakat) to Tashahhud ke baad keh kar khade ho jayein aur baqi rakatein padhein (teesri aur chauthi rakat farz mein sirf Surah Al-Fatiha, surah milana zaroori nahin).","h":0},{"t":"d","id":"d022","ti":"Qadam 15: Durood-e-Ibrahimi (aakhri qa'de mein)","pad":"Allaahumma salli 'alaa Muhammadin wa 'alaa aali Muhammad, kamaa sallayta 'alaa Ibraaheema wa 'alaa aali Ibraaheem, innaka Hameedum Majeed. Allaahumma baarik 'alaa Muhammadin wa 'alaa aali Muhammad, kamaa baarakta 'alaa Ibraaheema wa 'alaa aali Ibraaheem, innaka Hameedum Majeed.","tar":"Aye Allah! Muhammad ﷺ aur aal-e-Muhammad par rehmat naazil farma jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par rehmat naazil farmai, beshak tu taareef kiya gaya, buzurgi wala hai. Aye Allah! Muhammad ﷺ aur aal-e- Muhammad par barkat naazil farma jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par barkat naazil farmai, beshak tu taareef kiya gaya, buzurgi wala hai.","hi":"Ae Allah! Muhammad ﷺ aur aal-e-Muhammad par rehmat naazil kar jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par rehmat naazil ki, beshak tu tareef kiya gaya, badai wala hai. Ae Allah! Muhammad ﷺ aur aal-e- Muhammad par barkat naazil kar jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par barkat naazil ki, beshak tu tareef kiya gaya, badai wala hai.","pg":16,"i":"d022","in":["Aakhri rakat mein Tashahhud ke baad padhein:"]},{"t":"d","id":"d023","ti":"Qadam 16: Duaa-e-Masoora (aakhri qa'de mein)","pad":"Allaahumma innee zalamtu nafsee zulman katheeraa, wa laa yaghfiruz-zunooba illaa anta, faghfir lee maghfiratan min 'indika warhamnee, innaka antal-Ghafoorur-Raheem.","tar":"Aye Allah! Maine apni jaan par bahut zulm kiya aur tere siwa koi gunah bakhsh nahin sakta, pas tu apni khaas meherbani se mujhe bakhsh de aur mujh par reham farma, beshak tu hi bakhshne wala, reham karne wala hai.","hi":"Ae Allah! Maine apni jaan par bahut zulm kiya aur tere siwa koi gunah maaf nahin kar sakta, pas tu apni khaas meharbani se mujhe maaf kar de aur mujh par reham kar, beshak tu hi maaf karne wala, reham karne wala hai.","pg":17,"i":"d023"},{"t":"d","id":"d024","ti":"Doosri masnoon dua (Duaa-e-Masoora ke baad)","pad":"Rabbanaa aatinaa fid-dunyaa hasanatan wa fil-aakhirati hasanatan wa qinaa 'azaaban-naar.","tar":"Aye hamare Rab! Hamein dunya mein bhalai de aur aakhirat mein bhalai de aur hamein aag ke azaab se bacha.","hi":"Ae hamare Rab! Humein duniya mein bhalai de aur aakhirat mein bhalai de aur humein aag ke azaab se bacha.","pg":17,"i":"d024","in":["(Yeh dua Nabi ﷺ ne Hazrat Abu Bakr Siddeeq (radiyallahu anhu) ko namaz mein padhne ke liye sikhai.) Doosri masnoon dua bhi padhi ja sakti hai:"]},{"t":"d","id":"d025","ti":"Qadam 17: Salaam (namaz khatam karna)","pad":"Assalaamu 'alaykum wa rahmatullaah.","tar":"Tum par salaamati ho aur Allah ki rehmat ho.","hi":"Tum par salaamati ho aur Allah ki rehmat ho.","pg":18,"i":"d025","in":["Pehle daayein kandhe ki taraf munh pher kar, phir baayein taraf:"]},{"t":"p","s":"MashaAllah! Namaz mukammal ho gayi.","h":0}]},{"n":6,"t":"Rakaat ki tadaad (ek nazar mein)","b":[{"t":"i","i":"t02"},{"t":"p","s":"Teen rakat (Maghrib / Witr) ka tareeqa: Do rakat ke baad qa'de mein sirf At-Tahiyyaat padh kar khade ho jayein, teesri rakat padhein, phir aakhri qa'de mein At-Tahiyyaat, Durood-e-Ibrahimi, Duaa-e-Masoora padh kar salaam pheren.","h":0}]},{"n":7,"t":"Witr ki namaz aur Duaa-e-Qunoot","b":[{"t":"d","id":"d026","ti":"Duaa-e-Qunoot","pad":"Allaahummah-dinee feeman hadayt, wa 'aafinee feeman 'aafayt, wa tawallanee feeman tawallayt, wa baarik lee feemaa a'tayt, wa qinee sharra maa qadayt, fa innaka taqdee wa laa yuqdaa 'alayk, wa innahoo laa yazillu man waalayt, tabaarakta Rabbanaa wa ta'aalayt.","tar":"Aye Allah! Mujhe un logon mein hidayat de jin ko tu ne hidayat di, mujhe un mein aafiyat de jin ko tu ne aafiyat di, mujhe un mein apna dost bana jin ko tu ne apna dost banaya, jo kuch tu ne mujhe diya us mein barkat ata farma, aur jo faisla tu ne kiya us ki burai se mujhe bacha le. Beshak tu hi faisla karta hai aur tujh par koi faisla nahin chalta, aur jise tu apna dost bana le woh kabhi zaleel nahin hota. Aye hamare Rab! Tu bahut barkat wala aur buland hai.","hi":"Ae Allah! Mujhe un logon mein hidayat de jin ko tu ne hidayat di, mujhe un mein aafiyat de jin ko tu ne aafiyat di, mujhe un mein apna dost bana jin ko tu ne apna dost banaya, jo kuch tu ne mujhe diya us mein barkat ata kar, aur jo faisla tu ne kiya us ki burai se mujhe bacha le. Beshak tu hi faisla karta hai aur tujh par koi faisla nahin chalta, aur jise tu apna dost bana le woh kabhi zaleel (zillat wala) nahin hota. Ae hamare Rab! Tu bahut barkat wala aur buland hai.","pg":19,"i":"d026","in":["Witr ki teesri rakat mein Surah Fatiha aur surah ke baad kehte hue kaanon tak haath uthayein, phir haath baandh kar Duaa-e-Qunoot padhein:"]},{"t":"p","s":"(Jise yeh dua yaad na ho woh padh le, ya teen baar (Allaahummagh-fir lee) keh le.) Phir ruku karke namaz mukammal karein. mukammal karein.","h":0}]},{"n":8,"t":"Namaz ke baad ke azkaar (salaam ke foran baad)","b":[{"t":"d","id":"d027","ti":"1. Istighfaar (3 baar)","pad":"Astaghfirullaah.","tar":"Main Allah se bakhshish maangta hoon.","hi":"Main Allah se maafi maangta hoon.","pg":20,"i":"d027"},{"t":"d","id":"d028","ti":"2.","pad":"Allaahumma antas-salaam wa minkas-salaam, tabaarakta yaa Zal-Jalaali wal-Ikraam.","tar":"Aye Allah! Tu salaamati wala hai aur tujh hi se salaamati hai, tu barkat wala hai, aye buzurgi aur ikraam wale.","hi":"Ae Allah! Tu salaamati wala hai aur tujh hi se salaamati hai, tu barkat wala hai, ae badai aur ikraam wale.","pg":20,"i":"d028"},{"t":"d","id":"d029","ti":"3. Ayat-ul-Kursi (Hadees: farz namaz ke baad padhne wale ke liye jannat mein dakhile ki bashaarat hai)","pad":"Allaahu laa ilaaha illaa huwal-Hayyul-Qayyoom, laa ta'khuzuhoo sinatun wa laa nawm, lahoo maa fis-samaawaati wa maa fil-ard, man zal-lazee yashfa'u 'indahoo illaa bi-iznih, ya'lamu maa bayna aydeehim wa maa khalfahum, wa laa yuheetoona bishay'im-min 'ilmihee illaa bimaa shaa', wasi'a kursiyyuhus-samaawaati wal-ard, wa laa ya'ooduhoo hifzuhumaa, wa huwal-'Aliyyul-'Azeem.","tar":"Allah, us ke siwa koi maabood nahin, woh zinda hai, sab ko sambhalne wala hai. Use na unghh aati hai na neend. Aasmanon aur zameen mein jo kuchh hai usi ka hai. Kaun hai jo us ki ijaazat ke baghair us ke paas sifaarish kare? Woh jaanta hai jo un ke saamne hai aur jo un ke peeche hai, aur woh us ke ilm mein se kisi cheez ka ehata nahin kar sakte magar jitna woh chahe. Us ki kursi aasmanon aur zameen ko ghere hue hai aur in dono ki hifaazat use thakati nahin, aur wahi buland-o-azeem hai.","hi":"Allah, us ke siwa koi ma'bood (ibadat ke laayak) nahin, woh zinda hai, sab ko sambhalne wala hai. Use na unghh aati hai na neend. Aasmanon aur zameen mein jo kuchh hai usi ka hai. Kaun hai jo us ki ijaazat ke baghair us ke paas sifaarish kare? Woh jaanta hai jo un ke saamne hai aur jo un ke peeche hai, aur woh us ke ilm mein se kisi cheez ka ehata nahin kar sakte magar jitna woh chahe. Us ki kursi aasmanon aur zameen ko ghere hue hai aur in dono ki hifazat use thakati nahin, aur wahi buland-o-azeem hai.","pg":21,"i":"d029"},{"t":"p","s":"4. Tasbeehaat-e-Fatima (Hadees ke mutabiq)","h":0},{"t":"i","i":"t03"},{"t":"i","i":"t04"},{"t":"i","i":"t05"},{"t":"i","i":"t06"},{"t":"d","id":"d030","ti":"5. Ek aur masnoon dua","pad":"Allaahumma a'innee 'alaa zikrika wa shukrika wa husni 'ibaadatik.","tar":"Aye Allah! Apne zikr, apne shukr aur achhe tareeqe se apni ibaadat karne mein meri madad farma.","hi":"Ae Allah! Apne zikr, apne shukr aur achhe tareeqe se apni ibadat karne mein meri madad kar.","pg":22,"i":"d030"},{"t":"p","s":"Phir haath utha kar apni zabaan mein jo chahein dua maangein.","h":0}]},{"n":9,"t":"Namaz ke faraaiz (yaad rakhne ke liye)","b":[{"t":"p","s":"Namaz ke andar 7 farz:","h":0},{"t":"p","s":"1. Takbeer-e-Tahreema (Allahu Akbar keh kar shuru karna)","h":0},{"t":"p","s":"2. Qiyaam (khade ho kar padhna)","h":0},{"t":"p","s":"3. Qiraat (Quran padhna)","h":0},{"t":"p","s":"4. Ruku","h":0},{"t":"p","s":"5. Sajde (dono)","h":0},{"t":"p","s":"6. Qa'da-e-Akheera (aakhir mein Tashahhud ki miqdaar baithna)","h":0},{"t":"p","s":"7. Salaam ya koi amal jis se namaz se nikla jaye Namaz todne wali baatein: baat cheet, khana peena, bila uzr hansna, bila zaroorat zyada harkat karna, Qibla se seena phir lena, wudu toot jana. Agar namaz mein bhool ho jaye (wajib reh jaye) to aakhri qa'de mein At-Tahiyyaat ke baad daayein taraf ek salaam pher kar do sajda-e-sahw karein, phir dobara At-Tahiyyaat, Durood aur dua padh kar salaam pheren.","h":0}]},{"n":10,"t":"Nabi ﷺ ki sab se zyada padhi jaane wali duaein","b":[{"t":"p","s":"Hadees mein kisi ek dua ki gintee nahin aayi, lekin yeh woh duaein hain jinke baare mein sahih riwayaton mein aata hai ke Nabi ﷺ unhein sab se zyada ya baar-baar padhte the.","h":0},{"t":"d","id":"d031","ti":"1. Sab se zyada ki jaane wali dua (Hazrat Anas radiyallahu anhu ki riwayat)","pad":"Rabbanaa aatinaa fid-dunyaa hasanatan wa fil-aakhirati hasanatan wa qinaa 'azaaban-naar.","tar":"Aye hamare Rab! Hamein dunya mein bhalai de, aakhirat mein bhalai de aur hamein aag ke azaab se bacha.","hi":"Ae hamare Rab! Humein duniya mein bhalai de, aakhirat mein bhalai de aur humein aag ke azaab se bacha.","pg":24,"i":"d031","in":["Hazrat Anas (radiyallahu anhu) farmate hain ke Nabi ﷺ ki sab se zyada dua yeh hoti thi:"],"no":"Kab padhein: namaz ke aakhri qa'de mein (Durood ke baad), aur namaz ke baad dua mein."},{"t":"d","id":"d032","ti":"2. Ruku aur sajde mein baar-baar padhi jaane wali (Hazrat Aisha radiyallahu anha ki riwayat)","pad":"Subhaanakal-laahumma Rabbanaa wa bihamdik, Allaahummagh-fir lee.","tar":"Aye Allah! Aye hamare Rab! Tu paak hai apni hamd ke saath, aye Allah! Mujhe bakhsh de.","hi":"Ae Allah! Ae hamare Rab! Tu paak hai apni hamd ke saath, ae Allah! Mujhe maaf kar de.","pg":24,"i":"d032","in":["Hazrat Aisha (radiyallahu anha) farmati hain ke Nabi ﷺ ruku aur sajde mein yeh bahut kasrat se padhte the:"],"no":"Kab padhein: ruku aur sajde mein, tasbeeh (Subhaana Rabbiyal-'Azeem / Subhaana Rabbiyal- A'laa) padhne ke baad."},{"t":"d","id":"d033","ti":"3. Namaz shuru karne ki mashhoor dua (Bukhari aur Muslim)","pad":"Allaahumma baa'id baynee wa bayna khataayaaya kamaa baa'adta baynal-mashriqi wal- maghrib. Allaahumma naqqinee minal-khataayaa kamaa yunaqqath-thawbul-abyadu minad-danas. Allaahummaghsilnee min khataayaaya bith-thalji wal-maa'i wal-barad.","tar":"Aye Allah! Mere aur mere gunahon ke darmiyan itni doori kar de jitni mashriq aur maghrib ke darmiyan hai. Aye Allah! Mujhe gunahon se aise paak kar de jaise safed kapda mail se saaf kiya jaata hai. Aye Allah! Mere gunahon ko barf, paani aur olon se dho de.","hi":"Ae Allah! Mere aur mere gunahon ke darmiyan itni doori kar de jitni mashriq aur maghrib ke darmiyan hai. Ae Allah! Mujhe gunahon se aise paak kar de jaise safed kapda mail se saaf kiya jaata hai. Ae Allah! Mere gunahon ko barf, paani aur olon se dho de.","pg":25,"i":"d033","in":["Takbeer ke baad Nabi ﷺ yeh dua padhte the (Hanafi tareeqe mein Sana padhi jaati hai, doosre maslak mein yeh dua mashhoor hai; dono Nabi ﷺ se sabit hain):"]}]},{"n":11,"t":"Namaz-e-Janaza ka tareeqa","b":[{"t":"p","s":"Namaz-e-Janaza farz-e-kifaya hai (kuchh log padh lein to sab ki taraf se ada ho jaati hai). Isme ruku, sajda aur qa'da nahin hota, poori namaz khade ho kar padhi jaati hai. Azaan aur iqaamat nahin hoti. Wudu, paak kapde, paak jagah aur Qibla rukh zaroori hai. Tareeqa: Imam mayyit ke seene ke barabar khada ho, aur muqtadi uske peeche saf bana kar khade hon. 4 takbeerein hoti hain.","h":0},{"t":"p","s":"Niyyat","h":1},{"t":"p","s":"Dil mein iraada karein: Main Allah ke liye is janaze ki namaz padhta hoon, chaar takbeer ke saath, dua is mayyit ke liye, imam ke peeche, munh Qibla ki taraf.","h":0},{"t":"d","id":"d034","ti":"Pehli Takbeer","pad":"Subhaanakal-laahumma wa bihamdika, wa tabaarakasmuka, wa ta'aalaa jadduka, wa jalla thanaa'uka, wa laa ilaaha ghayruk.","tar":"Aye Allah! Tu paak hai apni hamd ke saath, tera naam barkat wala hai, teri shaan buland hai, teri taareef bahut badi hai aur tere siwa koi maabood nahin.","hi":"Ae Allah! Tu paak hai apni hamd ke saath, tera naam barkat wala hai, teri shaan buland hai, teri tareef bahut badi hai aur tere siwa koi ma'bood (ibadat ke laayak) nahin.","pg":26,"i":"d034","in":["kehte hue kaanon tak haath uthayein aur naaf ke neeche baandh lein. Phir Sana","padhein:"]},{"t":"d","id":"d035","ti":"Doosri Takbeer","pad":"Allaahumma salli 'alaa Muhammadin wa 'alaa aali Muhammad, kamaa sallayta 'alaa Ibraaheema wa 'alaa aali Ibraaheem, innaka Hameedum Majeed. Allaahumma baarik 'alaa Muhammadin wa 'alaa aali Muhammad, kamaa baarakta 'alaa Ibraaheema wa 'alaa aali Ibraaheem, innaka Hameedum Majeed.","tar":"Aye Allah! Muhammad ﷺ aur aal-e-Muhammad par rehmat naazil farma jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par rehmat naazil farmai, beshak tu taareef kiya gaya, buzurgi wala hai. Aye Allah! Muhammad ﷺ aur aal-e- Muhammad par barkat naazil farma jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par barkat naazil farmai, beshak tu taareef kiya gaya, buzurgi wala hai.","hi":"Ae Allah! Muhammad ﷺ aur aal-e-Muhammad par rehmat naazil kar jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par rehmat naazil ki, beshak tu tareef kiya gaya, badai wala hai. Ae Allah! Muhammad ﷺ aur aal-e- Muhammad par barkat naazil kar jaise tu ne Ibrahim (alayhis salaam) aur aal-e-Ibrahim par barkat naazil ki, beshak tu tareef kiya gaya, badai wala hai.","pg":27,"i":"d035","in":["kaho (haath uthaye baghair) aur Durood-e-Ibrahimi padhein:"]},{"t":"d","id":"d036","ti":"Teesri Takbeer","pad":"Allaahummagh-fir li-hayyinaa wa mayyitinaa, wa shaahidinaa wa gaa'ibinaa, wa sagheerinaa wa kabeerinaa, wa zakarinaa wa unthaanaa. Allaahumma man ahyaytahoo minnaa fa-ahyihee 'alal-Islaam, wa man tawaﬀaytahoo minnaa fa-tawaﬀahoo 'alal-eemaan.","tar":"Aye Allah! Hamare zinda aur hamare marne walon ko, hamare haazir aur gaayab ko, hamare chhoton aur hamare badon ko, hamare mardon aur hamari aurton ko bakhsh de. Aye Allah! Hum mein se jise tu zinda rakhe use Islam par zinda rakh aur jise maut de use imaan par maut de.","hi":"Ae Allah! Hamare zinda aur hamare marne walon ko, hamare haazir aur gaayab ko, hamare chhoton aur hamare badon ko, hamare mardon aur hamari aurton ko maaf kar de. Ae Allah! Hum mein se jise tu zinda rakhe use Islam par zinda rakh aur jise maut de use imaan par maut de.","pg":28,"i":"d036","in":["kaho (haath uthaye baghair) aur mayyit ke liye dua padhein.","Baaligh (mard ya aurat) ke liye:"]},{"t":"d","id":"d037","ti":"Nabaalig ladke ke liye:","pad":"Allaahummaj-'alhu lanaa farataa, waj-'alhu lanaa ajran wa zukhraa, waj-'alhu lanaa shaafi'an wa mushaﬀa'aa.","tar":"Aye Allah! Isse hamare liye aage jaane wala bana de, isse hamare liye ajr aur zakheera bana de, aur isse hamare liye aisa sifarishi bana de jiski sifarish qubool ho.","hi":"Ae Allah! Isse hamare liye aage jaane wala bana de, isse hamare liye ajr aur zakheera bana de, aur isse hamare liye aisa sifarishi bana de jiski sifaarish qubool ho.","pg":29,"i":"d037"},{"t":"d","id":"d038","ti":"Nabaalig ladki ke liye:","pad":"Allaahummaj-'alhaa lanaa farataa, waj-'alhaa lanaa ajran wa zukhraa, waj-'alhaa lanaa shaafi'atan wa mushaﬀa'ah.","tar":"Aye Allah! Isse hamare liye aage jaane wali bana de, isse hamare liye ajr aur zakheera bana de, aur isse hamare liye aisi sifarishi bana de jiski sifarish qubool ho.","hi":"Ae Allah! Isse hamare liye aage jaane wali bana de, isse hamare liye ajr aur zakheera bana de, aur isse hamare liye aisi sifarishi bana de jiski sifaarish qubool ho.","pg":29,"i":"d038"},{"t":"d","id":"d039","ti":"Chauthi Takbeer aur Salaam","pad":"Assalaamu 'alaykum wa rahmatullaah.","tar":"Tum par salaamati ho aur Allah ki rehmat ho.","hi":"Tum par salaamati ho aur Allah ki rehmat ho.","pg":30,"i":"d039","in":["kaho (haath uthaye baghair), phir haath chhod kar pehle daayein aur phir baayein taraf salaam pheren:"],"no":"Yaad rakhne ki baatein: Janaza mein Surah Fatiha Hanafi tareeqe mein dua ki niyyat se bhi padhi ja sakti hai magar zaroori nahin, aur Allah se mayyit ki maghfirat ki dua sab se bunyadi cheez hai. Agar koi dua yaad na ho to bas yeh kah lein: Aye Allah! Isse bakhsh de aur is par reham farma."}]},{"n":12,"t":"Hadees se — Ruku, Sajda aur Tashahhud ki duaein (references ke saath)","b":[{"t":"p","s":"Tashahhud ki duaein (references ke saath)","h":1},{"t":"p","s":"Yeh hissa hadees ki kitabon ke hawale se hai. Hanafi tareeqe mein farz namaz mein aam taur par ruku aur sajde ki tasbeeh padhi jaati hai, aur lambi duaein zyada tar nafl aur tahajjud mein. Is mein ulama ka thoda ikhtilaf hai, isliye apne aalim se bhi poochh lein.","h":0},{"t":"d","id":"x040","ti":"A. Ruku ki duaein","pad":"Subhaana Rabbiyal-'Azeem (wa bihamdih).","tar":"Mera azmat wala Rab paak hai (aur usi ki hamd ke saath).","hi":"Mera badi shaan wala Rab paak hai (aur usi ki hamd ke saath).","pg":30,"in":["1. Tasbeeh (sab se aam) — 3 baar ya zyada","(kuchh riwayaton mein ke izafe ke saath)"]},{"t":"d","id":"d041","ti":"2. Baar-baar padhi jaane wali (Sahih Bukhari 794, Sahih Muslim 484, Hazrat Aisha RA) Hazrat Aisha (RA) ke mutabiq Nabi ﷺ ruku aur sajde mein yeh bahut kasrat se padhte the:","pad":"Subhaanakal-laahumma Rabbanaa wa bihamdik, Allaahummagh-fir lee.","tar":"Aye Allah! Aye hamare Rab! Tu paak hai apni hamd ke saath, aye Allah! Mujhe bakhsh de.","hi":"Ae Allah! Ae hamare Rab! Tu paak hai apni hamd ke saath, ae Allah! Mujhe maaf kar de.","pg":31,"i":"d041"},{"t":"p","s":"3. Farishton aur Rooh ke Rab ki tasbeeh (Sahih Muslim 487,","h":0},{"t":"d","id":"d042","ti":"Hazrat Aisha RA)","pad":"Subbuhun Quddoosun Rabbul-malaa'ikati war-rooh.","tar":"Woh bahut paak aur muqaddas hai, farishton aur Rooh (Jibreel alayhis salaam) ka Rab.","hi":"Woh bahut paak aur muqaddas hai, farishton aur Rooh (Jibreel alayhis salaam) ka Rab.","pg":31,"i":"d042"},{"t":"d","id":"x043","ti":"B. Sajde ki duaein","pad":"Subhaana Rabbiyal-A'laa (wa bihamdih).","tar":"Mera sab se buland Rab paak hai (aur usi ki hamd ke saath).","hi":"Mera sab se buland Rab paak hai (aur usi ki hamd ke saath).","pg":31,"in":["Pehle yeh yaad rakhein: Hadees (Sahih Muslim 479) mein Nabi ﷺ ne farmaya ke ruku mein Rab ki azmat bayan karo aur sajde mein dua ki kasrat karo, kyunke woh dua ki qubooliyat ke qareeb hai. Ruku aur sajde mein Quran padhna mana hai.","1. Tasbeeh — 3 baar ya zyada","(kuchh riwayaton mein ke izafe ke saath)"]},{"t":"p","s":"2. Sajde mein bhi wahi dua jo ruku mein (Bukhari 794, Muslim 484 aur Muslim 487): Subhaanakal- laahumma Rabbanaa wa bihamdik, Allaahummagh-fir lee aur Subbuhun Quddoosun Rabbul- malaa'ikati war-rooh, upar ki tarah.","h":0},{"t":"p","s":"3. Gunahon ki muaafi ki dua (Sahih Muslim 483, Hazrat Abu","h":0},{"t":"d","id":"d044","ti":"Hurairah RA)","pad":"Allaahummagh-fir lee zanbee kullahoo, diqqahoo wa jillahoo, wa awwalahoo wa aakhirahoo, wa 'alaaniyatahoo wa sirrah.","tar":"Aye Allah! Mere saare gunah bakhsh de, chhote bhi aur bade bhi, pehle bhi aur baad ke bhi, khule bhi aur chhupe bhi.","hi":"Ae Allah! Mere saare gunah maaf kar de, chhote bhi aur bade bhi, pehle bhi aur baad ke bhi, khule bhi aur chhupe bhi.","pg":32,"i":"d044"},{"t":"d","id":"d045","ti":"4. Allah ki panaah ki dua (Sahih Muslim 486, Hazrat Aisha RA)","pad":"Allaahumma innee a'oozu bi-ridaaka min sakhatik, wa bi-mu'aafaatika min 'uqoobatik, wa a'oozu bika minka, laa uhsee thanaa'an 'alayka anta kamaa athnayta 'alaa nafsik.","tar":"Aye Allah! Main teri raza ki panaah leta hoon teri naaraazgi se, teri maafi ki panaah leta hoon teri saza se, aur main tujh se tera hi panaah maangta hoon. Main teri taareef ka shumaar nahin kar sakta, tu waisa hi hai jaisa tu ne khud apni taareef ki.","hi":"Ae Allah! Main teri raza ki panaah leta hoon teri naaraazgi se, teri maafi ki panaah leta hoon teri saza se, aur main tujh se tera hi panaah maangta hoon. Main teri tareef ka shumaar nahin kar sakta, tu waisa hi hai jaisa tu ne khud apni tareef ki.","pg":33,"i":"d045"},{"t":"d","id":"d046","ti":"5. Nafl aur tahajjud ka sajda (Sahih Muslim 771)","pad":"Allaahumma laka sajattu, wa laka aslamtu, wa bika aamantu, sajada wajhee lillazee khalaqahoo wa sawwarahoo, wa shaqqa sam'ahoo wa basarah, tabaarakallaahu ahsanul-khaaliqeen.","tar":"Aye Allah! Maine tere liye sajda kiya, tere liye farmabardaar hua aur tujh par imaan laaya. Mere chehre ne us zaat ko sajda kiya jis ne use banaya, shakl di, aur uske kaan aur aankh kholi. Allah barkat wala hai, sab se behtar banane wala.","hi":"Ae Allah! Maine tere liye sajda kiya, tere liye farmanbardar hua aur tujh par imaan laaya. Mere chehre ne us zaat ko sajda kiya jis ne use banaya, shakl di, aur uske kaan aur aankh kholi. Allah barkat wala hai, sab se behtar banane wala.","pg":33,"i":"d046"},{"t":"d","id":"d047","ti":"6. Ek aur dua (Sunan Nasai 1124)","pad":"Allaahummagh-fir lee maa asrartu wa maa a'lantu.","tar":"Aye Allah! Mujhe bakhsh de jo maine chhupa kar kiya aur jo maine khule aam kiya.","hi":"Ae Allah! Mujhe maaf kar de jo maine chhupa kar kiya aur jo maine khule aam kiya.","pg":34,"i":"d047"},{"t":"p","s":"C. Do sajdon ke darmiyan (Jalsa)","h":1},{"t":"p","s":"Nabi ﷺ se do tarah ki duaein aati hain: (Rabbigh-fir lee,","h":0},{"t":"p","s":"Rabbigh-fir lee) aur (Allaahummagh-fir lee warhamnee wahdinee wa 'aafinee warzuqnee). Dono ka tarjuma Hissa 5 (Qadam 11) mein hai.","h":0},{"t":"d","id":"d048","ti":"D. Tashahhud ke baad (salaam se pehle)","pad":"Allaahumma innee a'oozu bika min 'azaabi jahannam, wa min 'azaabil-qabr, wa min fitnatil- mahyaa wal-mamaat, wa min sharri fitnatil-maseehid-dajjaal.","tar":"Aye Allah! Main teri panaah maangta hoon jahannam ke azaab se, qabr ke azaab se, zindagi aur maut ke fitne se, aur maseeh dajjaal ke fitne ke shar se.","hi":"Ae Allah! Main teri panaah maangta hoon jahannam ke azaab se, qabr ke azaab se, zindagi aur maut ke fitne se, aur maseeh dajjaal ke fitne ke shar se.","pg":35,"i":"d048","in":["1. Chaar cheezon se panaah (Sahih Muslim 588, Hazrat Abu Hurairah RA) Nabi ﷺ ne farmaya: jab tum mein se koi aakhri Tashahhud se faarigh ho to Allah se chaar cheezon se panaah maange:"]},{"t":"p","s":"2. Gunah aur qarz se panaah (Sahih Bukhari 832 aur 833, Hazrat","h":0},{"t":"d","id":"d049","ti":"Aisha RA)","pad":"Allaahumma innee a'oozu bika minal-ma'thami wal-maghram.","tar":"Aye Allah! Main teri panaah maangta hoon gunah se aur qarz se.","hi":"Ae Allah! Main teri panaah maangta hoon gunah se aur qarz se.","pg":35,"i":"d049"},{"t":"p","s":"3. Duaa-e-Masoora (Sahih Bukhari 834, Hazrat Abu Bakr RA) — Hissa 5 (Qadam 16) mein likhi hui.","h":0},{"t":"p","s":"4. Apni pasand ki dua (Sahih Bukhari 835) Hazrat Abdullah ibn Masood (RA) ko Tashahhud sikhane ke baad Nabi ﷺ ne farmaya ke is ke baad jo dua chahe pasand kar ke maang le. Yaani Arabic masnoon duaon ke baad apni zaroorat ki dua bhi ki ja sakti hai. Tashahhud ke baad ki tarteeb: Tashahhud, phir Durood- e-Ibrahimi, phir yeh duaein (panaah wali aur Duaa-e-Masoora), phir salaam.","h":0}]},{"n":13,"t":"Farz namaz ke baad ke sunnat azkaar (Jhelum wali Quran & Sunnat Research Academy ke Green Card se)","b":[{"t":"d","id":"d050","ti":"ke Green Card se)","pad":"Allaahumma innee a'oozu bika minal-jubn, wa a'oozu bika minal-bukhl, wa a'oozu bika min an uradda ilaa ardhalil-'umur, wa a'oozu bika min fitnatid-dunyaa, wa a'oozu bika min 'azaabil-qabr.","tar":"Aye Allah! Main teri panaah mein aata hoon buzdili se, kanjoosi se, is baat se ke bahut nikammi umar tak pahunch jaaun, dunya ke fitne se, aur qabr ke azaab se.","hi":"Ae Allah! Main teri panaah mein aata hoon buzdili se, kanjoosi se, is baat se ke bahut nikammi umar tak pahunch jaaun, duniya ke fitne se, aur qabr ke azaab se.","pg":36,"i":"d050","in":["Yeh tamam azkaar salaam ke foran baad ke hain. Hissa 8 mein jo azkaar pehle aa chuke hain (Astaghfirullah 3 baar, Allahumma antas-salaam, Ayat-ul-Kursi, Tasbeehaat, Allahumma a'innee 'alaa zikrika, Rabbanaa aatinaa) un ke ilawa ye aur sunnat azkaar hain. Hadees ke numbers card par jaise chhape hain waise hi diye hain.","1. Azaab-e-Qabr aur kamzoriyon se panaah (Bukhari 2822, Hazrat Sa'd bin Abi Waqqas RA) — 1 baar"]},{"t":"d","id":"d051","ti":"2. Gunahon ki muaafi (Hazrat Ali RA, salaam ke baad) — 1 baar","pad":"Allaahummagh-fir lee maa qaddamtu wa maa akh-khartu, wa maa asrartu wa maa a'lantu, wa maa asraftu, wa maa anta a'lamu bihee minnee, antal-Muqaddimu wa antal- Mu'akhkhir, laa ilaaha illaa ant.","tar":"Aye Allah! Mere pehle aur baad ke gunah bakhsh de, jo maine chhupa kar kiye aur jo khule aam kiye, jo maine had se badh kar kiye aur jo tu mujh se zyada jaanta hai. Tu hi aage karne wala hai aur tu hi peechhe karne wala hai, tere siwa koi maabood nahin.","hi":"Ae Allah! Mere pehle aur baad ke gunah maaf kar de, jo maine chhupa kar kiye aur jo khule aam kiye, jo maine had se badh kar kiye aur jo tu mujh se zyada jaanta hai. Tu hi aage karne wala hai aur tu hi peechhe karne wala hai, tere siwa koi ma'bood (ibadat ke laayak) nahin.","pg":37,"i":"d051"},{"t":"d","id":"d052","ti":"3. Azaab se bachne ki dua (Muslim 1642) — 1 baar","pad":"Rabbi qinee 'azaabaka yawma tab'athu 'ibaadak.","tar":"Aye Rab! Mujhe apne azaab se bacha us din jab tu apne bandon ko uthayega.","hi":"Ae Rab! Mujhe apne azaab se bacha us din jab tu apne bandon ko uthayega.","pg":37,"i":"d052"},{"t":"d","id":"d053","ti":"4. Tauheed ka wazeefa (Bukhari 844, Muslim 1342, Hazrat Mughira bin Shu'ba RA) — 1 baar","pad":"Laa ilaaha illallaahu wahdahoo laa shareeka lah, lahul-mulku wa lahul-hamdu wa huwa 'alaa kulli shay'in qadeer. Allaahumma laa maani'a limaa a'tayta, wa laa mu'tiya limaa mana'ta, wa laa yanfa'u zal- jaddi minkal-jadd.","tar":"Allah ke siwa koi maabood nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai aur usi ke liye saari taareefein hain, aur woh har cheez par poori qudrat rakhta hai. Aye Allah! Jo tu de use koi rok nahin sakta aur jo tu rok le use koi de nahin sakta, aur kisi saahib-e-haisiyat ko tere muqable mein uski haisiyat faayda nahin deti.","hi":"Allah ke siwa koi ma'bood (ibadat ke laayak) nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai aur usi ke liye saari tareefein hain, aur woh har cheez par poori qudrat rakhta hai. Ae Allah! Jo tu de use koi rok nahin sakta aur jo tu rok le use koi de nahin sakta, aur kisi saahib-e-haisiyat ko tere muqable mein uski haisiyat faayda nahin deti.","pg":38,"i":"d053"},{"t":"d","id":"d054","ti":"5. Lambi tauheed ki dua (Muslim 1343, Hazrat Abdullah bin Zubair RA, buland awaaz se) — 1 baar","pad":"Laa ilaaha illallaahu wahdahoo laa shareeka lah, lahul-mulku wa lahul-hamdu wa huwa 'alaa kulli shay'in qadeer. Laa hawla wa laa quwwata illaa billaah. Laa ilaaha illallaahu wa laa na'budu illaa iyyaah. Lahun-ni'matu wa lahul-fadlu wa lahus-thanaa'ul-hasan. Laa ilaaha illallaahu mukhliseena lahud-deena wa law karihal-kaafiroon.","tar":"Allah ke siwa koi maabood nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai aur usi ke liye saari taareefein hain, woh har cheez par poori qudrat rakhta hai. Gunah se bachne ki himmat aur neki ki taaqat Allah ki taufeeq ke baghair nahin. Hum sirf usi ki ibaadat karte hain. Usi ki nematein hain, usi ka fazl hai aur usi ke liye achhi taareef hai. Hum khaalis usi ki bandagi karte hain chahe kaafir kitna hi bura samjhein.","hi":"Allah ke siwa koi ma'bood (ibadat ke laayak) nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai aur usi ke liye saari tareefein hain, woh har cheez par poori qudrat rakhta hai. Gunah se bachne ki himmat aur neki ki taaqat Allah ki taufeeq ke baghair nahin. Hum sirf usi ki ibadat karte hain. Usi ki neamtein hain, usi ka fazl hai aur usi ke liye achhi tareef hai. Hum khaalis usi ki bandagi karte hain chahe kaafir kitna hi bura samjhein.","pg":39,"i":"d054"},{"t":"d","id":"d055","ti":"6. Namaz ya majlis ke aakhir mein (Nasai 1344, Tirmidhi 3433, Hazrat Aisha RA) — 1 baar","pad":"Subhaanakal-laahumma wa bihamdik, ash-hadu al-laa ilaaha illaa ant, astaghfiruka wa atoobu ilayk.","tar":"Aye Allah! Tu paak hai apni hamd ke saath, main gawahi deta hoon ke tere siwa koi maabood nahin, main tujh se bakhshish maangta hoon aur teri taraf tauba karta hoon.","hi":"Ae Allah! Tu paak hai apni hamd ke saath, main gawahi deta hoon ke tere siwa koi ma'bood (ibadat ke laayak) nahin, main tujh se maafi maangta hoon aur teri taraf tauba karta hoon.","pg":40,"i":"d055"},{"t":"p","s":"7. Muawwizaat (Tirmidhi 2903, Abu Dawud 1523, Hazrat Uqba bin Aamir RA) — har namaz ke baad teeno surtein 1 baar Nabi ﷺ ne hukm diya ke har namaz ke baad Surah Ikhlaas, Surah Falaq aur Surah Naas padhi jaayein. (Surahon ka Arabic aur tarjuma Hissa 5 (Ikhlaas) aur Quran-e-Paak se dekh kar yaad karein.) 8. Tasbeehaat ka bada fazl (Bukhari 843, Muslim 1349 aur 1352, Hazrat Abu Hurairah RA) Har namaz ke baad Subhaanallaah, Alhamdulillaah, Allaahu Akbar teeno 33-33 baar, phir 100 poora karne ke liye ek baar:","h":0},{"t":"p","s":"(Ya 100 poora karne ke liye Allaahu Akbar ek baar aur.)","h":0},{"t":"p","s":"Fazl: Hadees mein hai ke aisa karne waale ke saare gunah maaf kar diye jaate hain chahe samundar ke jhaag ke barabar hon, aur woh kabhi naakaam aur naamuraad nahin rehta.","h":0},{"t":"p","s":"9. Maghrib aur Fajr ke baad (baat karne se pehle), 10 baar","h":0},{"t":"p","s":"(Tirmidhi 3474, Musnad Ahmad 18019, Hazrat Abdur Rahman bin","h":0},{"t":"d","id":"d056","ti":"Ghanm RA)","pad":"Laa ilaaha illallaahu wahdahoo laa shareeka lah, lahul-mulku wa lahul-hamd, biyadihil-khayr, yuhyee wa yumeet, wa huwa 'alaa kulli shay'in qadeer.","tar":"Allah ke siwa koi maabood nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi aur usi ke liye saari taareefein, uske haath mein bhalai hai, woh jilata aur maarta hai aur har cheez par poori qudrat rakhta hai.","hi":"Allah ke siwa koi ma'bood (ibadat ke laayak) nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi aur usi ke liye saari tareefein, uske haath mein bhalai hai, woh jilata aur maarta hai aur har cheez par poori qudrat rakhta hai.","pg":41,"i":"d056","no":"Fazl (card ke mutabiq): 10 gulam aazad karne ka sawab milta hai aur poore din aur raat har khatarnaak cheez aur shaitan se hifazat milti hai."},{"t":"p","s":"10. Maghrib aur Fajr ke baad 7 baar (Abu Dawud 5079, Hazrat","h":0},{"t":"d","id":"d057","ti":"Abu Haris RA)","pad":"Allaahumma ajirnee minan-naar.","tar":"Aye Allah! Mujhe aag se bacha le.","hi":"Ae Allah! Mujhe aag se bacha le.","pg":42,"i":"d057","no":"Fazl (card ke mutabiq): Jo Maghrib ke baad baat karne se pehle padhe aur usi raat wafaat paaye, ya Fajr ke baad padhe aur usi din wafaat paaye, woh dozakh ki aag se aazaad hoga."},{"t":"d","id":"d058","ti":"11. Sirf Fajr ki salaam ke baad (Ibn Majah 925, Ummul Momineen Umm Salama RA) — 1 baar","pad":"Allaahumma innee as-aluka 'ilman naafi'an, wa rizqan tayyiban, wa 'amalan mutaqabbalaa.","tar":"Aye Allah! Main tujh se faayda dene wala ilm, paakeeza rizq aur qubool hone wala amal maangta hoon.","hi":"Ae Allah! Main tujh se faayda dene wala ilm, paakeeza rizq aur qubool hone wala amal maangta hoon.","pg":42,"i":"d058"},{"t":"d","id":"d059","ti":"12. Witr ki salaam ke baad (Nasai 1699, Daraqutni 1679, Hazrat Abdur Rahman bin Abzaa RA) — 3 baar, teesri baar awaaz lambi aur buland","pad":"Subhaanal-Malikil-Quddoos.","tar":"Paak hai badshah, nihayat muqaddas.","hi":"Paak hai badshah, behad muqaddas.","pg":42,"i":"d059"},{"t":"p","s":"Teesri baar ke saath: (Rabbil-malaa'ikati war-rooh: farishton aur Jibreel ka Rab).","h":0},{"t":"p","s":"Durood ki ahmiyat (Tirmidhi 593): Allah ki hamd aur Nabi ﷺ par durood padhna duaon ki qubooliyat ka behtareen zariya hai. Namaz wala Durood-e-Ibrahimi Nabi ﷺ ne Surah Ahzaab ayat 56 ke jawab mein sikhaya tha (Bukhari 4797, Muslim 908). Tasbeeh gin'ne ke baare mein (card ke mutabiq):","h":0},{"t":"p","s":"Daayein haath ki ungliyon par gin'na sunnat se sabit hai (Abu Dawud 1501). Gutliyon ya tasbeeh par akele zikr karna bhi sabit hai (Abu Dawud 1500).","h":0}]},{"n":14,"t":"Subah aur Shaam ke sunnat azkaar (Blue Card se)","b":[{"t":"p","s":"Quran mein hukm hai: apne Rab ka zikr bahut zyada karo aur subah-shaam uski tasbeeh bayan karo (Surah Aal-e-Imran 41). Tirmidhi 3375 mein aaya hai ke Nabi ﷺ ne ek sahabi se farmaya: tumhari zabaan har waqt Allah ke zikr se tar rahe. Hadees ke numbers card ke mutabiq hain.","h":0},{"t":"p","s":"1. Ayat-ul-Kursi — 1 baar subah aur shaam (Bukhari 2311, Nasai Kubra 8017) Padhne waala shaitan aur jinnaat se mehfooz ho jaata hai. Poori ayat aur tarjuma Hissa 8 mein hai.","h":0},{"t":"p","s":"2. Muawwizaat (Surah Ikhlaas, Falaq, Naas) — teeno 3 baar subah aur shaam (Tirmidhi 3575, Abu Dawud 5082) Hadees mein hai ke yeh har cheez se kaafi ho jaati hain. Raat ko sone se pehle teeno ko 3 baar padh kar hatheliyon par phoonkna aur jism par dam karna sunnat hai (Bukhari 5017).","h":0},{"t":"d","id":"d060","ti":"3. Tauheed ka wazeefa — 10 baar subah aur shaam (Muslim 6844, Abu Dawud 5077)","pad":"Laa ilaaha illallaahu wahdahoo laa shareeka lah, lahul-mulku wa lahul-hamdu wa huwa 'alaa kulli shay'in qadeer.","tar":"Allah ke siwa koi maabood nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai, usi ke liye saari taareefein hain aur woh har cheez par poori qudrat rakhta hai.","hi":"Allah ke siwa koi ma'bood (ibadat ke laayak) nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai, usi ke liye saari tareefein hain aur woh har cheez par poori qudrat rakhta hai.","pg":43,"i":"d060","no":"Fazl: 4 gulam aazad karne ka sawab. Roz 100 baar padhna afzal amal hai (Bukhari 6403, Muslim 6842). 4. Allah ko Rab, Islam ko deen aur Nabi ﷺ ko Nabi maanne ka iqraar — 3 baar subah aur shaam (Abu Dawud 5072, Musnad Ahmad 18990)"},{"t":"d","id":"d061","ti":"4. Radeetu billaahi Rabbaa — 3 baar subah aur shaam","pad":"Radeetu billaahi Rabbaa, wa bil-Islaami deenaa, wa bi-Muhammadin nabiyyaa.","tar":"Main raazi hoon Allah ke Rab hone par, Islam ke deen hone par aur Muhammad ke Nabi hone par.","hi":"Main raazi hoon Allah ke Rab hone par, Islam ke deen hone par aur Muhammad ke Nabi hone par.","pg":44,"i":"d061","no":"Fazl (card ke mutabiq): Padhne waale par jannat wajib ho jaati hai aur Qayamat ke din Allah use khush kar dega."},{"t":"d","id":"d062","ti":"5. Har nuqsan se hifazat — 3 baar subah aur shaam (Tirmidhi 3388, Abu Dawud 5088)","pad":"Bismillaahil-lazee laa yadurru ma'asmihee shay'un fil-ardi wa laa fis-samaa'i wa huwas-Samee'ul- 'Aleem.","tar":"Allah ke naam ke saath, jiske naam ki barkat se zameen aur aasman mein koi cheez nuqsan nahin pahuncha sakti, aur wahi sunne waala, jaanne waala hai.","hi":"Allah ke naam ke saath, jiske naam ki barkat se zameen aur aasman mein koi cheez nuqsan nahin pahuncha sakti, aur wahi sunne waala, jaanne waala hai.","pg":44,"i":"d062"},{"t":"d","id":"d063","ti":"6. Zehreele jaanwar (bichhu, saanp, keede, machhar) ke shar se panaah — 3 baar subah aur shaam (Muslim 6880, Musnad Ahmad 7885)","pad":"A'oozu bikalimaatillaahit-taammaati min sharri maa khalaq.","tar":"Main Allah ke kaamil kalimaat ki panaah pakadta hoon har us cheez ke shar se jo us ne paida ki.","hi":"Main Allah ke kaamil kalimaat ki panaah pakadta hoon har us cheez ke shar se jo us ne paida ki.","pg":45,"i":"d063"},{"t":"d","id":"d064","ti":"7. Bahut bada ajr wali tasbeeh — 3 baar subah aur shaam (Muslim 6913)","pad":"Subhaanallaahi wa bihamdihee, 'adada khalqihee, wa ridaa nafsihee, wa zinata 'arshihee, wa midaada kalimaatih.","tar":"Allah paak hai aur apni taareef ke saath hai, apni makhlooq ki ginti ke barabar, apni raza ke barabar, apne Arsh ke wazan ke barabar aur apne kalimaat ki roshnai (siyahi) ke barabar.","hi":"Allah paak hai aur apni tareef ke saath hai, apni makhlooq ki ginti ke barabar, apni raza ke barabar, apne Arsh ke wazan ke barabar aur apne kalimaat ki roshnai (siyahi) ke barabar.","pg":45,"i":"d064"},{"t":"d","id":"d065","ti":"8. Istighfaar — 3 baar subah aur shaam (Tirmidhi 3577, Abu Dawud 1517)","pad":"Astaghfirullaahal-lazee laa ilaaha illaa huwal-Hayyul-Qayyoomu wa atoobu ilayh.","tar":"Main Allah se bakhshish maangta hoon jiske siwa koi maabood nahin, woh zinda hai, sab ko sambhalne waala hai, aur main usi ki taraf tauba karta hoon.","hi":"Main Allah se maafi maangta hoon jiske siwa koi ma'bood (ibadat ke laayak) nahin, woh zinda hai, sab ko sambhalne waala hai, aur main usi ki taraf tauba karta hoon.","pg":46,"i":"d065"},{"t":"d","id":"d066","ti":"9. Subah ki dua — 1 baar (Tirmidhi 3391)","pad":"Allaahumma bika asbahnaa, wa bika amsaynaa, wa bika nahyaa, wa bika namootu, wa ilaykan- nushoor.","tar":"Aye Allah! Tere naam ke saath hum ne subah ki, tere naam ke saath hum ne shaam ki, tere naam ke saath hum jeete hain aur tere naam ke saath marenge, aur tujh hi ki taraf marke uthna hai.","hi":"Ae Allah! Tere naam ke saath hum ne subah ki, tere naam ke saath hum ne shaam ki, tere naam ke saath hum jeete hain aur tere naam ke saath marenge, aur tujh hi ki taraf marke uthna hai.","pg":46,"i":"d066"},{"t":"p","s":"Shaam ko: (Amsaynaa wa bika asbahnaa) aur aakhir mein (wa ilaykal-maseer: aur teri hi taraf palatna hai).","h":0},{"t":"d","id":"d067","ti":"10. Fitrat-e-Islam par subah (Musnad Ahmad 15397) — 1 baar","pad":"Asbahnaa 'alaa fitratil-Islaam, wa 'alaa kalimatil-ikhlaas, wa 'alaa deeni nabiyyinaa Muhammadin , wa 'alaa millati abeenaa Ibraaheema haneefan musliman wa maa kaana minal-mushrikeen.","tar":"Hum ne subah ki Islam ki fitrat par, kalima-e-ikhlaas par, apne Nabi Muhammad ﷺ ke deen par aur apne baap Ibrahim (alayhis salaam) ki millat par jo yaksu Muslim the aur mushrikon mein se nahin the.","hi":"Hum ne subah ki Islam ki fitrat par, kalima-e-ikhlaas par, apne Nabi Muhammad ﷺ ke deen par aur apne baap Ibrahim (alayhis salaam) ki millat par jo yaksu Muslim the aur mushrikon (shirk karne walon) mein se nahin the.","pg":47,"i":"d067"},{"t":"p","s":"Shaam ko: (Amsaynaa) se shuru karein.","h":0},{"t":"d","id":"d068","ti":"11. Subah-shaam ki jaame dua (Muslim 6908) — 1 baar","pad":"Asbahnaa wa asbahal-mulku lillaah, walhamdu lillaah, laa ilaaha illallaahu wahdahoo laa shareeka lah, lahul-mulku wa lahul-hamdu wa huwa 'alaa kulli shay'in qadeer. Rabbi as-aluka khayra maa fee haazal-yawmi wa khayra maa ba'dah, wa a'oozu bika min sharri maa fee haazal-yawmi wa sharri maa ba'dah. Rabbi a'oozu bika minal-kasali wa soo'il-kibar, Rabbi a'oozu bika min 'azaabin fin-naari wa 'azaabin fil-qabr.","tar":"Hum ne subah ki aur Allah ke mulk ne subah ki, aur saari taareefein Allah ke liye hain. Allah ke siwa koi maabood nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai aur usi ke liye saari taareefein, woh har cheez par poori qudrat rakhta hai. Aye mere Rab! Main tujh se is din ki bhalai maangta hoon aur jo is ke baad hai, aur is din ke shar aur jo is ke baad hai us ke shar se teri panaah maangta hoon. Aye mere Rab! Main sustee aur burhape ki buraai se teri panaah maangta hoon. Aye mere Rab! Main aag ke azaab aur qabr ke azaab se teri panaah maangta hoon.","hi":"Hum ne subah ki aur Allah ke mulk ne subah ki, aur saari tareefein Allah ke liye hain. Allah ke siwa koi ma'bood (ibadat ke laayak) nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai aur usi ke liye saari tareefein, woh har cheez par poori qudrat rakhta hai. Ae mere Rab! Main tujh se is din ki bhalai maangta hoon aur jo is ke baad hai, aur is din ke shar aur jo is ke baad hai us ke shar se teri panaah maangta hoon. Ae mere Rab! Main sustee aur burhape ki buraai se teri panaah maangta hoon. Ae mere Rab! Main aag ke azaab aur qabr ke azaab se teri panaah maangta hoon.","pg":48,"i":"d068"},{"t":"p","s":"Shaam ko: , aur (is raat aur is ke baad).","h":0},{"t":"d","id":"d069","ti":"12. Sayyidul Istighfaar (Bukhari 6306) — 1 baar subah aur shaam","pad":"Allaahumma anta Rabbee, laa ilaaha illaa ant, khalaqtanee wa anaa 'abduk, wa anaa 'alaa 'ahdika wa wa'dika mastata'tu, a'oozu bika min sharri maa sana'tu, aboo'u laka bi-ni'matika 'alayya, wa aboo'u bi-zanbee faghfir lee, fa-innahoo laa yaghfiruz-zunooba illaa ant.","tar":"Aye Allah! Tu hi mera Rab hai, tere siwa koi maabood nahin, tu ne mujhe paida kiya aur main tera banda hoon, aur jitni meri taaqat hai main tere ahd aur wade par qaayam hoon. Jo kuchh maine kiya us ke shar se teri panaah maangta hoon. Apne upar teri nemat ka iqraar karta hoon aur apne gunah ka aitraaf karta hoon, pas mujhe bakhsh de, kyunke tere siwa koi gunah bakhsh nahin sakta.","hi":"Ae Allah! Tu hi mera Rab hai, tere siwa koi ma'bood (ibadat ke laayak) nahin, tu ne mujhe paida kiya aur main tera banda hoon, aur jitni meri taaqat hai main tere ahd aur wade par qaayam hoon. Jo kuchh maine kiya us ke shar se teri panaah maangta hoon. Apne upar teri neamat ka iqraar karta hoon aur apne gunah ka aitraaf karta hoon, pas mujhe maaf kar de, kyunke tere siwa koi gunah maaf nahin kar sakta.","pg":49,"i":"d069","no":"Fazl (card ke mutabiq, hadees ke mafhoom mein): Jo koi subah ya shaam poore yaqeen ke saath ise padhe aur usi din ya raat mein faut ho jaaye to jannati hoga."},{"t":"d","id":"d070","ti":"13. Subhaanallaahi wa bihamdih — 100 baar subah aur shaam (Bukhari 6405, Muslim 6842)","pad":"Subhaanallaahi wa bihamdih.","tar":"Allah paak hai aur apni taareef ke saath hai.","hi":"Allah paak hai aur apni tareef ke saath hai.","pg":50,"i":"d070","no":"Fazl: Saare gunah maaf kar diye jaate hain chahe samundar ke jhaag ke barabar hon."},{"t":"d","id":"d071","ti":"14. Tauba aur istighfaar — din bhar mein 100 baar (Bukhari 6307, Muslim 6858)","pad":"Astaghfirullaaha wa atoobu ilayh.","tar":"Main Allah se bakhshish maangta hoon aur usi ki taraf tauba karta hoon.","hi":"Main Allah se maafi maangta hoon aur usi ki taraf tauba karta hoon.","pg":50,"i":"d071"},{"t":"p","s":"15. Chaar fazeelat wale azkaar — din bhar mein 100 baar (Nasai Kubra 10680) Subhaanallaah, Alhamdulillaah, Allaahu Akbar, Laa ilaaha illallaah. Card ke mutabiq in ka sawab 100 ghode jihad mein, 100 gulam aazad karne, 100 oont Allah ki raah mein qurbaan karne ka hai, aur Laa ilaaha illallaah zameen aur aasman ko bhar deta hai.","h":0},{"t":"d","id":"d072","ti":"16. Jannat ka khazana (Bukhari 6409, Muslim 6862)","pad":"Laa hawla wa laa quwwata illaa billaah.","tar":"Gunah se bachne ki himmat aur neki karne ki taaqat Allah ki taufeeq ke baghair nahin.","hi":"Gunah se bachne ki himmat aur neki karne ki taaqat Allah ki taufeeq ke baghair nahin.","pg":50,"i":"d072"},{"t":"d","id":"d073","ti":"17. Mushkil halaat mein (Aal-e-Imran 173, Bukhari 4563)","pad":"Hasbunallaahu wa ni'mal-wakeel.","tar":"Hamein Allah kaafi hai aur woh behtareen kaarsaaz hai.","hi":"Humein Allah kaafi hai aur woh behtareen madadgaar hai.","pg":51,"i":"d073"},{"t":"p","s":"Raat ke wazeefe: Surah Baqarah ki aakhri 2 ayaat raat mein 1 baar padhna kaafi ho jaata hai (Bukhari 4008, Muslim 1878). Raat ko Surah Al-Mulk padhna padhne waale ki sifarish karta rehta hai yahan tak ke uski bakhshish kar di jaaye (Abu Dawud 1400).","h":0},{"t":"d","id":"d074","ti":"18. Apne tamam kaam sanwarne ki dua (Mustadrak Hakim 2000) — subah aur shaam","pad":"Yaa Hayyu yaa Qayyoomu bi-rahmatika astagheeth, aslih lee sha'nee kullahoo, wa laa takilnee ilaa nafsee tarfata 'ayn.","tar":"Aye zinda, aye sab ko sambhalne waale! Main teri rehmat ke saath tujh se madad maangta hoon. Mere tamam kaam mere liye durust kar de aur mujhe palak jhapakne ke barabar bhi mere nafs ke hawale na kar.","hi":"Ae zinda, ae sab ko sambhalne waale! Main teri rehmat ke saath tujh se madad maangta hoon. Mere tamam kaam mere liye durust kar de aur mujhe palak jhapakne ke barabar bhi mere nafs ke hawale na kar.","pg":51,"i":"d074"},{"t":"d","id":"d075","ti":"19. Aafiyat ki jaame dua (Abu Dawud 5074) — subah aur shaam","pad":"Allaahumma innee as-alukal-'aafiyata fid-dunyaa wal-aakhirah. Allaahumma innee as-alukal- 'afwa wal-'aafiyata fee deenee wa dunyaaya wa ahlee wa maalee. Allaahummastur 'awraatee wa aamin raw'aatee. Allaahummah-fazhnee min bayni yadayya wa min khalfee wa 'an yameenee wa 'an shimaalee wa min fawqee, wa a'oozu bi-'azamatika an ughtaala min tahtee.","tar":"Aye Allah! Main tujh se dunya aur aakhirat mein aafiyat maangta hoon. Aye Allah! Main tujh se maafi aur aafiyat maangta hoon apne deen mein, apni dunya mein, apne ghar waalon mein aur apne maal mein. Aye Allah! Meri chhupi cheezon par parda daal de aur meri ghabrahaton ko aman mein badal de.","hi":"Ae Allah! Main tujh se duniya aur aakhirat mein aafiyat maangta hoon. Ae Allah! Main tujh se maafi aur aafiyat maangta hoon apne deen mein, apni duniya mein, apne ghar waalon mein aur apne maal mein. Ae Allah! Meri chhupi cheezon par parda daal de aur meri ghabrahaton ko aman mein badal de.","pg":52,"i":"d075"},{"t":"p","s":"Aye Allah! Meri hifaazat farma mere aage se, mere peechhe se, mere daayein se, mere baayein se aur mere upar se, aur main teri azmat ki panaah leta hoon is se ke achaanak neeche se halaak kar diya jaaun.","h":0},{"t":"d","id":"d076","ti":"20. Nafs aur shaitan ke shar se panaah (Tirmidhi 3392) — subah aur shaam","pad":"Allaahumma 'aalimal-ghaybi wash-shahaadah, faatiras-samaawaati wal-ard, Rabba kulli shay'in wa maleekah, ash-hadu al-laa ilaaha illaa ant, a'oozu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkih.","tar":"Aye Allah! Ghaib aur haazir ke jaanne waale, aasmanon aur zameen ke paida karne waale, har cheez ke Rab aur maalik! Main gawahi deta hoon ke tere siwa koi maabood nahin. Main teri panaah leta hoon apne nafs ke shar se, aur shaitan ke shar se aur us ke shirk (us ke jaal mein shareek karne) se.","hi":"Ae Allah! Ghaib aur haazir ke jaanne waale, aasmanon aur zameen ke paida karne waale, har cheez ke Rab aur maalik! Main gawahi deta hoon ke tere siwa koi ma'bood (ibadat ke laayak) nahin. Main teri panaah leta hoon apne nafs ke shar se, aur shaitan ke shar se aur us ke shirk (us ke jaal mein shareek karne) se.","pg":53,"i":"d076"}]},{"n":15,"t":"Hisn-ul-Muslim se namaz ki aur duaein (Imam Sa'eed Al-Qahtani)","b":[{"t":"p","s":"Yeh duaein Hisn-ul-Muslim ke un hisson se hain jo namaz ke ruku, qawma, sajde aur jalsa se talluq rakhte hain. Dua ka number Hisn-ul-Muslim ke index ke mutabiq hai.","h":0},{"t":"d","id":"d077","ti":"Ruku ki aur duaein (Hisn dua 17)","pad":"Allaahumma laka raka'tu, wa bika aamantu, wa laka aslamtu, khasha'a laka sam'ee, wa basaree, wa mukhkhee, wa 'azmee, wa 'asabee, wa maa istaqalla bihee qadamee.","tar":"Aye Allah! Maine tere liye ruku kiya, tujh par imaan laaya aur tere liye farmabardaar hua. Mere kaan, meri aankhein, mera bhejha, meri haddiyan, mere pathe aur mera poora badan jis par mere dono paon khade hain, tere liye jhuk gaye.","hi":"Ae Allah! Maine tere liye ruku kiya, tujh par imaan laaya aur tere liye farmanbardar hua. Mere kaan, meri aankhein, mera bhejha, meri haddiyan, mere pathe aur mera poora badan jis par mere dono paon khade hain, tere liye jhuk gaye.","pg":54,"i":"d077","in":["Ruku ki dua (Muslim, Tirmidhi, Nasai, Abu Dawud)"]},{"t":"p","s":"Badshahi aur azmat ki tasbeeh (Abu Dawud, Ahmad, Nasai;","h":0},{"t":"d","id":"d078","ti":"sanad hasan)","pad":"Subhaana zil-jabarooti wal-malakooti wal-kibriyaa'i wal-'azamah.","tar":"Paak hai woh jo badi taaqat, bade mulk, badai aur azmat wala hai.","hi":"Paak hai woh jo badi taaqat, bade mulk, badai aur badi shaan wala hai.","pg":55,"i":"d078"},{"t":"d","id":"d079","ti":"Ruku se uthne ki duaein (Hisn dua 18)","pad":"Rabbanaa wa lakal-hamd, hamdan katheeran tayyiban mubaarakan feeh.","tar":"Aye hamare Rab! Tere hi liye saari taareefein hain, bahut zyada, paakeeza taareef jis mein barkat rakhi gayi hai.","hi":"Ae hamare Rab! Tere hi liye saari tareefein hain, bahut zyada, paakeeza tareef jis mein barkat rakhi gayi hai.","pg":55,"i":"d079","in":["1. Rabbanaa wa lakal-hamd (Bukhari)"]},{"t":"d","id":"d080","ti":"2. Lambi dua (Muslim)","pad":"Mil'as-samaawaati wa mil'al-ardi wa maa baynahumaa, wa mil'a maa shi'ta min shay'in ba'd. Ahlath-thanaa'i wal-majd, ahaqqu maa qaalal-'abd, wa kulluna laka 'abd. Allaahumma laa maani'a limaa a'tayta, wa laa mu'tiya limaa mana'ta, wa laa yanfa'u zal-jaddi minkal-jadd.","tar":"(Aye hamare Rab!) Tere hi liye taareef hai aasmanon ke bharne ke barabar, zameen ke bharne ke barabar, un dono ke darmiyan jo kuchh hai uske bharne ke barabar aur is ke baad jo tu chahe uske bharne ke barabar. Tu taareef aur buzurgi wala hai, sab se sachchi baat jo banda keh sakta hai (aur hum sab tere hi bande hain) yeh hai: aye Allah! Jo tu de use koi rok nahin sakta aur jo tu rok le use koi de nahin sakta, aur kisi shaan wale ko uski shaan tere yahan faayda nahin deti.","hi":"(Ae hamare Rab!) Tere hi liye tareef hai aasmanon ke bharne ke barabar, zameen ke bharne ke barabar, un dono ke darmiyan jo kuchh hai uske bharne ke barabar aur is ke baad jo tu chahe uske bharne ke barabar. Tu tareef aur badai wala hai, sab se sachchi baat jo banda keh sakta hai (aur hum sab tere hi bande hain) yeh hai: ae Allah! Jo tu de use koi rok nahin sakta aur jo tu rok le use koi de nahin sakta, aur kisi shaan wale ko uski shaan tere yahan faayda nahin deti.","pg":56,"i":"d080"},{"t":"p","s":"Sajde ki duaein (Hisn dua 19)","h":1},{"t":"p","s":"Sajde ki tamam duaein Hissa 12 (B) mein hain. Hisn-ul-Muslim ki fehrist ke mutabiq yeh bhi hain: Subhaana Rabbiyal-A'laa (3 baar): Abu Dawud, Tirmidhi, Nasai, Ibn Majah, Ahmad Subhaanakal-laahumma Rabbanaa wa bihamdik, Allaahummagh-fir lee (Bukhari, Muslim) Subbuhun Quddoosun Rabbul-malaa'ikati war-rooh (Muslim, Abu Dawud) Allaahumma laka sajattu... (Muslim) Subhaana zil-jabarooti wal-malakooti wal-kibriyaa'i wal-'azamah (Abu Dawud, Nasai, Ahmad) Allaahummagh-fir lee zanbee kullahoo... (Muslim) Allaahumma innee a'oozu bi-ridaaka min sakhatik... (Muslim)","h":0},{"t":"d","id":"d081","ti":"Do sajdon ke darmiyan ki duaein (Hisn dua 20)","pad":"Allaahummagh-fir lee, warhamnee, wahdinee, wajburnee, wa 'aafinee, warzuqnee, warfa'nee.","tar":"Aye Allah! Mujhe bakhsh de, mujh par reham farma, mujhe hidayat de, meri kamiyan poori kar de, mujhe aafiyat de, mujhe rizq ata farma aur mera martaba buland kar.","hi":"Ae Allah! Mujhe maaf kar de, mujh par reham kar, mujhe hidayat de, meri kamiyan poori kar de, mujhe aafiyat de, mujhe rizq ata kar aur mera martaba buland kar.","pg":57,"i":"d081","in":["1. (Rabbigh-fir lee, Rabbigh-fir lee) — Abu Dawud, Ibn Majah.","2. Lambi dua (Abu Dawud, Ibn Majah)"]}]},{"n":16,"t":"Roz-marra ki zaroori duaein (Hisn-ul-Muslim ke mutabiq)","b":[{"t":"p","s":"Har dua ke saath Hisn-ul-Muslim ka number diya hai. Jahan number nahin hai wahan duaein usi kitaab ke dusre hisson se hain.","h":0},{"t":"d","id":"d082","ti":"1. Neend se jaagne ke baad (Hisn dua 1, Bukhari)","pad":"Alhamdu lillaahil-lazee ahyaanaa ba'da maa amaatanaa wa ilayhin-nushoor.","tar":"Saari taareef Allah ke liye jis ne hamein maut (neend) ke baad zinda kiya aur usi ki taraf uthna hai.","hi":"Saari tareef Allah ke liye jis ne humein maut (neend) ke baad zinda kiya aur usi ki taraf uthna hai.","pg":58,"i":"d082"},{"t":"d","id":"d083","ti":"2. Kapde pehente waqt (Hisn dua 2, Abu Dawud, Tirmidhi)","pad":"Alhamdu lillaahil-lazee kasaanee haazas-thawba wa razaqaneehi min ghayri hawlin minnee wa laa quwwah.","tar":"Saari taareef Allah ke liye jis ne mujhe yeh kapda pehnaya aur mujhe ata kiya, mere kisi zor aur taaqat ke baghair.","hi":"Saari tareef Allah ke liye jis ne mujhe yeh kapda pehnaya aur mujhe ata kiya, mere kisi zor aur taaqat ke baghair.","pg":58,"i":"d083"},{"t":"d","id":"d084","ti":"3. Naya kapda pehente waqt (Hisn dua 3, Abu Dawud, Tirmidhi)","pad":"Allaahumma lakal-hamdu anta kasawtaneehi, as-aluka min khayrihee wa khayri maa suni'a lah, wa a'oozu bika min sharrihee wa sharri maa suni'a lah.","tar":"Aye Allah! Tere hi liye taareef hai, tu ne mujhe yeh pehnaya. Main tujh se is ki bhalai aur jis maqsad ke liye yeh bana hai uski bhalai maangta hoon, aur is ke shar aur jis maqsad ke liye bana hai uske shar se teri panaah maangta hoon.","hi":"Ae Allah! Tere hi liye tareef hai, tu ne mujhe yeh pehnaya. Main tujh se is ki bhalai aur jis maqsad ke liye yeh bana hai uski bhalai maangta hoon, aur is ke shar aur jis maqsad ke liye bana hai uske shar se teri panaah maangta hoon.","pg":59,"i":"d084"},{"t":"d","id":"d085","ti":"4. Baitul-khala (toilet) mein jaane se pehle (Hisn dua 6, Bukhari, Muslim)","pad":"Bismillaah, Allaahumma innee a'oozu bika minal-khubuthi wal-khabaa'ith.","tar":"Allah ke naam se. Aye Allah! Main teri panaah maangta hoon nar aur maada shaitaanon se.","hi":"Allah ke naam se. Ae Allah! Main teri panaah maangta hoon nar aur maada shaitaanon se.","pg":59,"i":"d085"},{"t":"d","id":"d086","ti":"5. Baitul-khala se nikalte waqt (Hisn dua 7, Abu Dawud, Tirmidhi, Ibn Majah)","pad":"Ghufraanak.","tar":"Aye Allah! Main tujh se bakhshish maangta hoon.","hi":"Ae Allah! Main tujh se maafi maangta hoon.","pg":60,"i":"d086"},{"t":"p","s":"6. Wudu shuru karne se pehle (Hisn dua 8) aur wudu ke baad (Hisn dua 9)","h":1},{"t":"p","s":"Shuru mein Bismillaah aur baad ki dua Hissa 2 mein likhi hui hai.","h":0},{"t":"d","id":"d087","ti":"7. Ghar se nikalte waqt (Hisn dua 10, Abu Dawud, Tirmidhi)","pad":"Bismillaah, tawakkaltu 'alallaah, wa laa hawla wa laa quwwata illaa billaah.","tar":"Allah ke naam se, maine Allah par bharosa kiya, aur gunah se bachne ki himmat aur neki ki taaqat Allah ki taufeeq ke baghair nahin.","hi":"Allah ke naam se, maine Allah par bharosa kiya, aur gunah se bachne ki himmat aur neki ki taaqat Allah ki taufeeq ke baghair nahin.","pg":60,"i":"d087","no":"Fazl: Hadees mein hai ke is dua ke baad kaha jaata hai: tujhe hidayat di gayi, tujhe kaafi hua aur tu bacha liya gaya, aur shaitan us se door ho jaata hai."},{"t":"d","id":"d088","ti":"8. Ghar mein dakhil hote waqt (Hisn dua 11, Abu Dawud)","pad":"Bismillaahi walajnaa, wa bismillaahi kharajnaa, wa 'alallaahi Rabbinaa tawakkalnaa.","tar":"Allah ke naam se hum andar aaye, Allah ke naam se hum bahar nikle, aur apne Rab Allah par hum ne bharosa kiya. (Phir ghar waalon ko salaam karein.)","hi":"Allah ke naam se hum andar aaye, Allah ke naam se hum bahar nikle, aur apne Rab Allah par hum ne bharosa kiya. (Phir ghar waalon ko salaam karein.)","pg":61,"i":"d088"},{"t":"d","id":"d089","ti":"9. Masjid ki taraf jaate waqt (Hisn dua 12, Muslim)","pad":"Allaahummaj-'al fee qalbee noora, wa fee lisaanee noora, waj-'al fee sam'ee noora, waj-'al fee basaree noora, waj-'al min khalfee noora, wa min amaamee noora, waj-'al min fawqee noora, wa min tahtee noora. Allaahumma a'tinee noora.","tar":"Aye Allah! Mere dil mein noor kar de, meri zabaan mein noor, mere kaanon mein noor, meri aankhon mein noor, mere peechhe noor, mere aage noor, mere upar noor aur mere neeche noor kar de.","hi":"Ae Allah! Mere dil mein noor kar de, meri zabaan mein noor, mere kaanon mein noor, meri aankhon mein noor, mere peechhe noor, mere aage noor, mere upar noor aur mere neeche noor kar de.","pg":61,"i":"d089"},{"t":"p","s":"Aye Allah! Mujhe noor ata farma.","h":0},{"t":"p","s":"10. Masjid mein dakhil hone aur nikalne ki dua (Hisn dua 13 aur 14)","h":1},{"t":"p","s":"Dono duaein Hissa 3 mein likhi hui hain. Dakhil hote waqt seedha paon aur nikalte waqt ulta paon pehle rakhein, aur dono waqt Nabi ﷺ par durood aur salaam bhejna bhi sunnat hai.","h":0},{"t":"d","id":"d090","ti":"11. Sone ke waqt ki duaein (Hisn dua 28)","pad":"Bismikal-laahumma amootu wa ahyaa.","tar":"Aye Allah! Tere hi naam ke saath main marta aur jeeta hoon.","hi":"Ae Allah! Tere hi naam ke saath main marta aur jeeta hoon.","pg":62,"i":"d090","in":["Sone ki dua (Bukhari)"]},{"t":"p","s":"Sone se pehle (Bukhari, Muslim): Ayat-ul-Kursi padhna, aur Surah Ikhlaas, Falaq aur Naas teen baar padh kar hatheliyon par phoonk kar poore badan par haath pherna. Surah Baqarah ki aakhri do ayaat bhi padhna sunnat hai.","h":0},{"t":"d","id":"x091","ti":"12. Raat ko neend ya ghabrahat mein (Hisn dua 29 aur 30)","pad":"A'oozu bikalimaatillaahit-taammaati min ghadabihee wa 'iqaabihee wa sharri 'ibaadihee, wa min hamazaatish-shayaateeni wa ay-yahdurun.","tar":"Main Allah ke kaamil kalimaat ki panaah maangta hoon uske ghusse aur saza se, uske bandon ke shar se, shaitanon ke waswason se aur is baat se ke woh mere paas aayein.","hi":"Main Allah ke kaamil kalimaat ki panaah maangta hoon uske ghusse aur saza se, uske bandon ke shar se, shaitanon ke waswason se aur is baat se ke woh mere paas aayein.","pg":62,"in":["Ghabrahat ya bechaini ki dua:","(Abu Dawud, Tirmidhi)."]},{"t":"d","id":"d092","ti":"13. Khaane ki duaein","pad":"Alhamdu lillaahil-lazee at'amanee haazaa wa razaqaneehi min ghayri hawlin minnee wa laa quwwah.","tar":"Saari taareef Allah ke liye jis ne mujhe yeh khilaya aur mujhe ata kiya, mere kisi zor aur taaqat ke baghair.","hi":"Saari tareef Allah ke liye jis ne mujhe yeh khilaya aur mujhe ata kiya, mere kisi zor aur taaqat ke baghair.","pg":63,"i":"d092","in":["Khaane se pehle: (Bismillaah). Agar shuru mein bhool jaaye to yaad aane par:","(Bismillaahi awwalahoo wa aakhirah: Allah ke naam se is ke shuru aur aakhir mein).","Khaane ke baad (Abu Dawud, Tirmidhi):"]},{"t":"d","id":"d093","ti":"14. Sawaari par sawaar hone ki dua (Hisn dua 95, Abu Dawud, Tirmidhi)","pad":"Subhaanal-lazee sakhkhara lanaa haazaa wa maa kunnaa lahoo muqrineen, wa innaa ilaa Rabbinaa la-munqaliboon.","tar":"Paak hai woh jis ne is ko hamare kaabu mein kar diya, warna hum ise kaabu mein nahin kar sakte the, aur beshak hum apne Rab ki taraf palat kar jaane waale hain.","hi":"Paak hai woh jis ne is ko hamare kaabu mein kar diya, warna hum ise kaabu mein nahin kar sakte the, aur beshak hum apne Rab ki taraf palat kar jaane waale hain.","pg":64,"i":"d093","in":["Sawaari par baith kar Bismillaah aur Alhamdulillaah kahein, phir:"]},{"t":"d","id":"d094","ti":"15. Mushkil ya musibat ke waqt","pad":"Innaa lillaahi wa innaa ilayhi raaji'oon. Allaahumma-jurnee fee museebatee wa akhlif lee khayran minhaa.","tar":"Beshak hum Allah ke liye hain aur usi ki taraf lautne waale hain. Aye Allah! Meri is musibat mein mujhe ajr de aur mujhe is se behtar badla ata farma. (Muslim)","hi":"Beshak hum Allah ke liye hain aur usi ki taraf lautne waale hain. Ae Allah! Meri is musibat mein mujhe ajr de aur mujhe is se behtar badla ata kar. (Muslim)","pg":64,"i":"d094"},{"t":"p","s":"16. Istikhara ki dua (Hisn dua 26, Bukhari)","h":1},{"t":"p","s":"Jab kisi kaam mein faisla na kar paayein to do rakat nafl namaz padh kar dua padhein. Dua ka tarjuma aur wazaahat apne aalim se seekh lein, kyunke yeh lambi dua hai jis mein apna kaam zikr kiya jaata hai.","h":0}]},{"n":17,"t":"Quran ki duaein","b":[{"t":"p","s":"Quran mein Allah ne apne bandon ko dua maangna sikhaya hai. Yeh sab se mashhoor aur zaroori duaein hain, Surah aur ayat ke number ke saath. Is mein Quran ki saari duaein nahin, balki sab se zyada padhi jaane wali chuni hui duaein hain.","h":0},{"t":"d","id":"d095","ti":"1. Aasan dua jo Quran ne sikhayi","pad":"Rabbanaa aatinaa fid-dunyaa hasanatan wa fil-aakhirati hasanatan wa qinaa 'azaaban-naar.","tar":"Aye hamare Rab! Hamein dunya mein bhalai de, aakhirat mein bhalai de aur hamein aag ke azaab se bacha.","hi":"Ae hamare Rab! Humein duniya mein bhalai de, aakhirat mein bhalai de aur humein aag ke azaab se bacha.","pg":65,"i":"d095","in":["Dunya aur aakhirat ki bhalai (Al-Baqarah 2:201)"]},{"t":"d","id":"d096","ti":"Bhool chook par pakad na ho (Al-Baqarah 2:286)","pad":"Rabbanaa laa tu'aakhiznaa in naseenaa aw akhta'naa. Rabbanaa wa laa tahmil 'alaynaa isran kamaa hamaltahoo 'alal-lazeena min qablinaa. Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih, wa'fu 'annaa waghfir lanaa warhamnaa, anta mawlaanaa fansurnaa 'alal-qawmil-kaafireen.","tar":"Aye hamare Rab! Agar hum bhool jaayein ya galti karein to hamein na pakad. Aye hamare Rab! Hum par woh bojh na daal jo tu ne hum se pehle logon par daala tha. Aye hamare Rab! Hum se woh na uthwa jis ki hamein taaqat nahin. Hamein maaf kar de, hamein bakhsh de aur hum par reham farma. Tu hi hamara maalik hai, pas kaafir qaum ke muqable mein hamari madad farma.","hi":"Ae hamare Rab! Agar hum bhool jaayein ya galti karein to humein na pakad. Ae hamare Rab! Hum par woh bojh na daal jo tu ne hum se pehle logon par daala tha. Ae hamare Rab! Hum se woh na uthwa jis ki humein taaqat nahin. Humein maaf kar de, humein maaf kar de aur hum par reham kar. Tu hi hamara maalik hai, pas kaafir qaum ke muqable mein hamari madad kar.","pg":66,"i":"d096"},{"t":"d","id":"d097","ti":"Dil seedha rahe (Aal-e-Imran 3:8)","pad":"Rabbanaa laa tuzigh quloobanaa ba'da iz hadaytanaa wa hab lanaa min ladunka rahmah, innaka antal-Wahhaab.","tar":"Aye hamare Rab! Hidayat dene ke baad hamare dilon ko tedha na kar, aur hamein apne paas se rehmat ata farma, beshak tu hi bahut ata karne wala hai.","hi":"Ae hamare Rab! Hidayat dene ke baad hamare dilon ko tedha na kar, aur humein apne paas se rehmat ata kar, beshak tu hi bahut ata karne wala hai.","pg":66,"i":"d097"},{"t":"d","id":"d098","ti":"Gunah ki muaafi aur aag se bachaao (Aal-e-Imran 3:16)","pad":"Rabbanaa innanaa aamannaa faghfir lanaa zunoobanaa wa qinaa 'azaaban-naar.","tar":"Aye hamare Rab! Hum imaan laaye, pas hamare gunah bakhsh de aur hamein aag ke azaab se bacha.","hi":"Ae hamare Rab! Hum imaan laaye, pas hamare gunah maaf kar de aur humein aag ke azaab se bacha.","pg":67,"i":"d098"},{"t":"d","id":"d099","ti":"Sabr aur saabit qadmi (Al-Baqarah 2:250)","pad":"Rabbanaa afrigh 'alaynaa sabran wa sabbit aqdaamanaa wansurnaa 'alal-qawmil-kaafireen.","tar":"Aye hamare Rab! Hum par sabr undel de, hamare qadam jamaa de aur kaafir qaum ke muqable mein hamari madad farma.","hi":"Ae hamare Rab! Hum par sabr undel de, hamare qadam jamaa de aur kaafir qaum ke muqable mein hamari madad kar.","pg":67,"i":"d099"},{"t":"d","id":"d100","ti":"Noor ki takmeel (At-Tahreem 66:8)","pad":"Rabbanaa atmim lanaa noorana waghfir lanaa, innaka 'alaa kulli shay'in qadeer.","tar":"Aye hamare Rab! Hamara noor poora kar de aur hamein bakhsh de, beshak tu har cheez par poori qudrat rakhta hai.","hi":"Ae hamare Rab! Hamara noor poora kar de aur humein maaf kar de, beshak tu har cheez par poori qudrat rakhta hai.","pg":68,"i":"d100"},{"t":"d","id":"d101","ti":"Jahannam ke azaab se panaah (Al-Furqaan 25:65)","pad":"Rabbanas-rif 'annaa 'azaaba jahannam, inna 'azaabahaa kaana gharaamaa.","tar":"Aye hamare Rab! Hum se jahannam ka azaab door rakh, beshak uska azaab chimat jaane wala hai.","hi":"Ae hamare Rab! Hum se jahannam ka azaab door rakh, beshak uska azaab chimat jaane wala hai.","pg":68,"i":"d101"},{"t":"d","id":"d102","ti":"Biwi bachon aur parhezgaari ki dua (Al-Furqaan 25:74)","pad":"Rabbanaa hab lanaa min azwaajinaa wa zurriyyaatinaa qurrata a'yunin waj-'alnaa lil-muttaqeena imaamaa.","tar":"Aye hamare Rab! Hamein hamari biwiyon aur aulaad se aankhon ki thandak ata farma aur hamein parhezgaaron ka imaam bana.","hi":"Ae hamare Rab! Humein hamari biwiyon aur aulaad se aankhon ki thandak ata kar aur humein parhezgaaron ka imaam bana.","pg":69,"i":"d102"},{"t":"d","id":"d103","ti":"Maa baap aur momineen ke liye (Ibrahim 14:41)","pad":"Rabbanagh-fir lee wa li-waalidayya wa lil-mu'mineena yawma yaqoomul-hisaab.","tar":"Aye hamare Rab! Mujhe, mere maa baap ko aur sab imaan walon ko us din bakhsh de jis din hisaab qaayam hoga.","hi":"Ae hamare Rab! Mujhe, mere maa baap ko aur sab imaan walon ko us din maaf kar de jis din hisaab qaayam hoga.","pg":69,"i":"d103"},{"t":"d","id":"d104","ti":"Maa baap par reham ki dua (Bani Israeel 17:24)","pad":"Rabbir-hamhumaa kamaa rabbayaanee sagheeraa.","tar":"Aye mere Rab! In dono par reham farma jaise inhon ne bachpan mein mujhe paala.","hi":"Ae mere Rab! In dono par reham kar jaise inhon ne bachpan mein mujhe paala.","pg":70,"i":"d104"},{"t":"d","id":"d105","ti":"Ilm mein izafa (Taa-Haa 20:114)","pad":"Rabbi zidnee 'ilmaa.","tar":"Aye mere Rab! Mere ilm mein izafa farma.","hi":"Ae mere Rab! Mere ilm mein izafa kar.","pg":70,"i":"d105"},{"t":"d","id":"d106","ti":"Shaitani waswason se panaah (Al-Mu'minoon 23:97 aur 98)","pad":"Rabbi a'oozu bika min hamazaatish-shayaateen, wa a'oozu bika Rabbi ay-yahdurooni.","tar":"Aye mere Rab! Main shaitanon ke waswason se teri panaah maangta hoon, aur aye mere Rab! Is se bhi teri panaah maangta hoon ke woh mere paas aayein.","hi":"Ae mere Rab! Main shaitanon ke waswason se teri panaah maangta hoon, aur ae mere Rab! Is se bhi teri panaah maangta hoon ke woh mere paas aayein.","pg":71,"i":"d106"},{"t":"d","id":"d107","ti":"Bakhshish aur rehmat (Al-Mu'minoon 23:118)","pad":"Rabbigh-fir warham wa anta khayrur-raahimeen.","tar":"Aye mere Rab! Bakhsh de aur reham farma, aur tu sab se behtar reham karne wala hai.","hi":"Ae mere Rab! Bakhsh de aur reham kar, aur tu sab se behtar reham karne wala hai.","pg":71,"i":"d107"},{"t":"d","id":"d108","ti":"2. Ashaab-e-Kahf (Ghaar waalon) ki dua (Al-Kahf 18:10)","pad":"Rabbanaa aatinaa min ladunka rahmatan wa hayyi' lanaa min amrinaa rashadaa.","tar":"Aye hamare Rab! Hamein apni taraf se rehmat ata farma aur hamare kaam mein hamare liye hidayat ka saamaan paida kar de.","hi":"Ae hamare Rab! Humein apni taraf se rehmat ata kar aur hamare kaam mein hamare liye hidayat ka saamaan paida kar de.","pg":71,"i":"d108","in":["Jab naujawan fitne se bachne ke liye panaah lene ke liye ghaar mein pahunche to unhon ne yeh dua ki:"]},{"t":"d","id":"d109","ti":"3. Safar, naye safar aur mushkil raaston ki dua (Bani Israeel 17:80)","pad":"Rabbi adkhilnee mudkhala sidqin wa akhrijnee mukhraja sidqin waj-'al lee min ladunka sultaanan naseeraa.","tar":"Aye mere Rab! Mujhe jahan bhi tu le jaaye sachchai ke saath le ja, aur jahan se bhi nikaale sachchai ke saath nikaal, aur mere liye apne paas se ghalba aur madad muqarrar farma de.","hi":"Ae mere Rab! Mujhe jahan bhi tu le jaaye sachchai ke saath le ja, aur jahan se bhi nikaale sachchai ke saath nikaal, aur mere liye apne paas se ghalba aur madad muqarrar kar de.","pg":72,"i":"d109","in":["Yeh dua aapke screenshot mein bhi hai (video ka unwaan: \"Har museebat aur pareshani ki dua\"):"]},{"t":"d","id":"d110","ti":"4. Nabi ﷺ ki khwab mein sikhayi hui dua (Tirmidhi 3235)","pad":"Allaahumma innee as-aluka fi'lal-khayraati wa tarkal-munkaraati wa hubbal-masaakeen, wa an taghfira lee wa tarhamanee, wa izaa aradta fitnata qawmin fa-tawaﬀanee ghayra maftoon, as-aluka hubbaka wa hubba man yuhibbuka wa hubba 'amalin yuqarribu ilaa hubbik.","tar":"Aye Allah! Main tujh se bhale kaamon ke karne aur burai ke kaamon ke chhodne ki taufeeq maangta hoon, aur miskeenon se mohabbat, aur yeh ke tu mujhe maaf kar de aur mujh par reham farma. Aur jab tu kisi qaum ko aazmaish mein daalna chahe to mujhe fitne mein padne se pehle maut de de. Main tujh se teri mohabbat maangta hoon, aur us shakhs ki mohabbat jo tujh se mohabbat kare, aur us amal ki mohabbat jo teri mohabbat ke qareeb kar de.","hi":"Ae Allah! Main tujh se bhale kaamon ke karne aur burai ke kaamon ke chhodne ki taufeeq maangta hoon, aur miskeenon se mohabbat, aur yeh ke tu mujhe maaf kar de aur mujh par reham kar. Aur jab tu kisi qaum ko aazmaish mein daalna chahe to mujhe fitne mein padne se pehle maut de de. Main tujh se teri mohabbat maangta hoon, aur us shakhs ki mohabbat jo tujh se mohabbat kare, aur us amal ki mohabbat jo teri mohabbat ke qareeb kar de.","pg":73,"i":"d110","in":["Aapke screenshot mein yeh dua hai (video ka unwaan: \"Nabi ﷺ ka khwab mein dua\"). Is mein neki karne, burai chhodne, miskeenon aur Allah se mohabbat ka sawaal hai:"]}]},{"n":18,"t":"Ambiya (Paighambaron) ki duaein jo Quran mein hain","b":[{"t":"p","s":"Har nabi ki dua ke saath Surah aur ayat ka number diya hai. Yeh sab duaein Quran mein Allah ne naqal farmayi hain, taake hum bhi unhein padh sakein.","h":0},{"t":"d","id":"d111","ti":"Hazrat Adam (alayhis salaam) aur Hazrat Hawwa — Al-A'raaf 7:23","pad":"Rabbanaa zalamnaa anfusanaa wa il-lam taghfir lanaa wa tarhamnaa lanakoonanna minal- khaasireen.","tar":"Aye hamare Rab! Hum ne apni jaanon par zulm kiya, aur agar tu ne hamein na bakhsha aur hum par reham na farmaya to hum zaroor nuqsan uthane walon mein se ho jaayenge.","hi":"Ae hamare Rab! Hum ne apni jaanon par zulm kiya, aur agar tu ne humein na bakhsha aur hum par reham na farmaya to hum zaroor nuqsan uthane walon mein se ho jaayenge.","pg":74,"i":"d111"},{"t":"d","id":"d112","ti":"Hazrat Nooh (alayhis salaam)","pad":"Rabbi innee a'oozu bika an as-alaka maa laysa lee bihee 'ilm, wa illaa taghfir lee wa tarhamnee akum minal-khaasireen.","tar":"Aye mere Rab! Main teri panaah maangta hoon is se ke tujh se woh cheez maangoon jis ka mujhe ilm nahin, aur agar tu mujhe na bakhshe aur mujh par reham na kare to main nuqsan uthane walon mein se ho jaaunga.","hi":"Ae mere Rab! Main teri panaah maangta hoon is se ke tujh se woh cheez maangoon jis ka mujhe ilm nahin, aur agar tu mujhe na maaf kare aur mujh par reham na kare to main nuqsan uthane walon mein se ho jaaunga.","pg":75,"i":"d112","in":["Allah se woh na maangna jis ka ilm na ho (Hood 11:47)"]},{"t":"d","id":"d113","ti":"Barkat wali jagah utarna (Al-Mu'minoon 23:29)","pad":"Rabbi anzilnee munzalan mubaarakan wa anta khayrul-munzileen.","tar":"Aye mere Rab! Mujhe barkat wali jagah utaar, aur tu sab se behtar utaarne wala hai.","hi":"Ae mere Rab! Mujhe barkat wali jagah utaar, aur tu sab se behtar utaarne wala hai.","pg":76,"i":"d113"},{"t":"d","id":"d114","ti":"Maa baap aur imaan walon ke liye (Nooh 71:28)","pad":"Rabbigh-fir lee wa li-waalidayya wa liman dakhala baytiya mu'minan wa lil-mu'mineena wal- mu'minaat.","tar":"Aye mere Rab! Mujhe, mere maa baap ko, jo imaan ke saath mere ghar mein dakhil ho use, aur sab imaan waale mardon aur imaan wali aurton ko bakhsh de.","hi":"Ae mere Rab! Mujhe, mere maa baap ko, jo imaan ke saath mere ghar mein dakhil ho use, aur sab imaan waale mardon aur imaan wali aurton ko maaf kar de.","pg":76,"i":"d114"},{"t":"d","id":"d115","ti":"Hazrat Ibrahim (alayhis salaam)","pad":"Rabbanaa taqabbal minnaa, innaka antas-Samee'ul-'Aleem.","tar":"Aye hamare Rab! Hum se (yeh amal) qubool farma, beshak tu hi sunne waala, jaanne waala hai.","hi":"Ae hamare Rab! Hum se (yeh amal) qubool kar, beshak tu hi sunne waala, jaanne waala hai.","pg":76,"i":"d115","in":["Qubooliyat ki dua (Al-Baqarah 2:127, Ibrahim aur Ismail","alayhimas salaam ne Kaaba banate waqt)"]},{"t":"d","id":"d116","ti":"Farmabardaar qaum ki dua (Al-Baqarah 2:128)","pad":"Rabbanaa waj-'alnaa muslimayni laka wa min zurriyyatinaa ummatan muslimatan lak.","tar":"Aye hamare Rab! Hum dono ko apna farmabardaar bana aur hamari aulaad mein se bhi ek ummat bana jo tere hukm ki farmabardaar ho.","hi":"Ae hamare Rab! Hum dono ko apna farmanbardar bana aur hamari aulaad mein se bhi ek ummat bana jo tere hukm ki farmanbardar ho.","pg":77,"i":"d116"},{"t":"d","id":"d117","ti":"Aman wale shehar ki dua (Ibrahim 14:35)","pad":"Rabbij-'al haazal-balada aaminan wajnubnee wa baniyya an na'budal-asnaam.","tar":"Aye mere Rab! Is shehar ko aman wala bana de aur mujhe aur meri aulaad ko is se bacha ke hum button ki ibaadat karein.","hi":"Ae mere Rab! Is shehar ko aman wala bana de aur mujhe aur meri aulaad ko is se bacha ke hum button ki ibadat karein.","pg":77,"i":"d117"},{"t":"d","id":"d118","ti":"Namaz qaayam karne ki dua (Ibrahim 14:40)","pad":"Rabbij-'alnee muqeemas-salaati wa min zurriyyatee, Rabbanaa wa taqabbal du'aa'.","tar":"Aye mere Rab! Mujhe namaz qaayam karne wala bana aur meri aulaad mein se bhi. Aye hamare Rab! Meri dua qubool farma.","hi":"Ae mere Rab! Mujhe namaz qaayam karne wala bana aur meri aulaad mein se bhi. Ae hamare Rab! Meri dua qubool kar.","pg":78,"i":"d118"},{"t":"d","id":"d119","ti":"Hukm aur nek logon ke saath (Ash-Shu'araa 26:83)","pad":"Rabbi hab lee hukman wa alhiqnee bis-saaliheen.","tar":"Aye mere Rab! Mujhe hikmat (hukm) ata farma aur mujhe nek logon ke saath mila de.","hi":"Ae mere Rab! Mujhe hikmat (hukm) ata kar aur mujhe nek logon ke saath mila de.","pg":78,"i":"d119"},{"t":"d","id":"d120","ti":"Tawakkul ki dua (Al-Mumtahina 60:4)","pad":"Rabbanaa 'alayka tawakkalnaa wa ilayka anabnaa wa ilaykal-maseer.","tar":"Aye hamare Rab! Hum ne tujh par bharosa kiya, tujh hi ki taraf rujoo kiya aur tujh hi ki taraf lautna hai.","hi":"Ae hamare Rab! Hum ne tujh par bharosa kiya, tujh hi ki taraf rujoo kiya aur tujh hi ki taraf lautna hai.","pg":79,"i":"d120"},{"t":"d","id":"d121","ti":"Hazrat Yunus (alayhis salaam) — Al-Anbiyaa 21:87","pad":"Laa ilaaha illaa anta subhaanaka innee kuntu minaz-zaalimeen.","tar":"Tere siwa koi maabood nahin, tu paak hai, beshak main hi zalimon mein se tha.","hi":"Tere siwa koi ma'bood (ibadat ke laayak) nahin, tu paak hai, beshak main hi zalimon mein se tha.","pg":79,"i":"d121","in":["Yeh dua unhon ne machhli ke pet ke andheron mein ki thi:"],"no":"Fazl: Hadees (Tirmidhi) mein hai ke koi Muslim jis cheez ke liye bhi is dua se dua kare, Allah use qubool farmata hai."},{"t":"d","id":"d122","ti":"Hazrat Moosa (alayhis salaam)","pad":"Rabbish-rah lee sadree, wa yassir lee amree, wahlul 'uqdatan min lisaanee, yafqahoo qawlee.","tar":"Aye mere Rab! Mera seena khol de, mera kaam mere liye aasan kar de, meri zabaan ki girah khol de taake woh meri baat samajh sakein.","hi":"Ae mere Rab! Mera seena khol de, mera kaam mere liye aasan kar de, meri zabaan ki girah khol de taake woh meri baat samajh sakein.","pg":80,"i":"d122","in":["Seena kholne aur kaam aasan hone ki dua (Taa-Haa 20:25 se 28)"]},{"t":"d","id":"d123","ti":"Muhtaaji aur zaroorat ki dua (Al-Qasas 28:24)","pad":"Rabbi innee limaa anzalta ilayya min khayrin faqeer.","tar":"Aye mere Rab! Jo bhi bhalai tu mere liye utaare main uska muhtaaj hoon.","hi":"Ae mere Rab! Jo bhi bhalai tu mere liye utaare main uska muhtaaj hoon.","pg":80,"i":"d123"},{"t":"d","id":"d124","ti":"Zalimon se najaat (Al-Qasas 28:21)","pad":"Rabbi najjinee minal-qawmiz-zaalimeen.","tar":"Aye mere Rab! Mujhe zalim logon se najaat de.","hi":"Ae mere Rab! Mujhe zalim logon se najaat de.","pg":80,"i":"d124"},{"t":"d","id":"d125","ti":"Hazrat Ayyub (alayhis salaam) — Al-Anbiyaa 21:83","pad":"Annee massaniyad-durru wa anta arhamur-raahimeen.","tar":"Mujhe takleef pahunchi hai aur tu sab se zyada reham karne wala hai.","hi":"Mujhe takleef pahunchi hai aur tu sab se zyada reham karne wala hai.","pg":81,"i":"d125","in":["Sakht bimari aur takleef mein:"]},{"t":"d","id":"d126","ti":"Hazrat Zakariya (alayhis salaam)","pad":"Rabbi hab lee min ladunka zurriyyatan tayyibah, innaka samee'ud-du'aa'.","tar":"Aye mere Rab! Mujhe apni taraf se paakeeza aulaad ata farma, beshak tu dua sunne waala hai.","hi":"Ae mere Rab! Mujhe apni taraf se paakeeza aulaad ata kar, beshak tu dua sunne waala hai.","pg":81,"i":"d126","in":["Nek aulaad ki dua (Aal-e-Imran 3:38)"]},{"t":"d","id":"d127","ti":"Akele na rehne ki dua (Al-Anbiyaa 21:89)","pad":"Rabbi laa tazarnee fardan wa anta khayrul-waariseen.","tar":"Aye mere Rab! Mujhe akela na chhod, aur tu sab se behtar waaris hai.","hi":"Ae mere Rab! Mujhe akela na chhod, aur tu sab se behtar waaris hai.","pg":82,"i":"d127"},{"t":"d","id":"d128","ti":"Hazrat Sulaiman (alayhis salaam) — An-Naml 27:19","pad":"Rabbi awzi'nee an ashkura ni'mataka allatee an'amta 'alayya wa 'alaa waalidayya wa an a'mala saalihan tardaahu wa adkhilnee bi-rahmatika fee 'ibaadikas-saaliheen.","tar":"Aye mere Rab! Mujhe taufeeq de ke main teri us nemat ka shukr ada karoon jo tu ne mujh par aur mere maa baap par ki, aur main aisa nek amal karoon jis se tu raazi ho, aur mujhe apni rehmat se apne nek bandon mein shamil farma.","hi":"Ae mere Rab! Mujhe taufeeq de ke main teri us neamat ka shukr ada karoon jo tu ne mujh par aur mere maa baap par ki, aur main aisa nek amal karoon jis se tu raazi ho, aur mujhe apni rehmat se apne nek bandon mein shaamil kar.","pg":82,"i":"d128"},{"t":"d","id":"d129","ti":"Hazrat Yusuf (alayhis salaam) — Yusuf 12:101","pad":"Faatiras-samaawaati wal-ard, anta waliyyee fid-dunyaa wal-aakhirah, tawaﬀanee muslimaw wa alhiqnee bis-saaliheen.","tar":"Aye aasmanon aur zameen ke paida karne wale! Tu hi dunya aur aakhirat mein mera kaarsaaz hai. Mujhe islam ki haalat mein maut de aur mujhe nek logon ke saath mila de.","hi":"Ae aasmanon aur zameen ke paida karne wale! Tu hi duniya aur aakhirat mein mera madadgaar hai. Mujhe islam ki haalat mein maut de aur mujhe nek logon ke saath mila de.","pg":83,"i":"d129"},{"t":"d","id":"d130","ti":"Hazrat Lut (alayhis salaam) — Ash-Shu'araa 26:169","pad":"Rabbi najjinee wa ahlee mimmaa ya'maloon.","tar":"Aye mere Rab! Mujhe aur mere ghar waalon ko us (gandagi) se bacha le jo yeh log karte hain.","hi":"Ae mere Rab! Mujhe aur mere ghar waalon ko us (gandagi) se bacha le jo yeh log karte hain.","pg":83,"i":"d130"},{"t":"d","id":"d131","ti":"Hazrat Shu'aib (alayhis salaam) — Al-A'raaf 7:89","pad":"Rabbanaf-tah baynanaa wa bayna qawminaa bil-haqqi wa anta khayrul-faatiheen.","tar":"Aye hamare Rab! Hamare aur hamari qaum ke darmiyan haq ke saath faisla farma de, aur tu sab se behtar faisla karne wala hai.","hi":"Ae hamare Rab! Hamare aur hamari qaum ke darmiyan haq ke saath faisla kar de, aur tu sab se behtar faisla karne wala hai.","pg":84,"i":"d131"},{"t":"d","id":"d132","ti":"Hazrat Nooh (alayhis salaam) — Al-Qamar 54:10","pad":"Annee maghloobun fantasir.","tar":"Main maghloob (kamzor) hoon, pas tu (meri) madad farma.","hi":"Main maghloob (kamzor) hoon, pas tu (meri) madad kar.","pg":84,"i":"d132","in":["Jab qaum ne unhein jhutlaya:"]}]},{"n":19,"t":"Namaz mein Nabi ﷺ ki duaein — shuru se","b":[{"t":"p","s":"salaam tak, tarteeb se","h":1},{"t":"p","s":"Yeh hissa sahih ahadees ki roshni mein hai. Pehle tarteeb ek nazar mein, phir woh duaein jo abhi tak document mein nahin thi.","h":0},{"t":"p","s":"Namaz mein dua ki tarteeb (ek nazar mein)","h":1},{"t":"i","i":"t07"},{"t":"d","id":"d133","ti":"1. Namaz shuru karne ki lambi dua (Sahih Muslim 771, Hazrat Ali RA)","pad":"Wajjahtu wajhiya lillazee fataras-samaawaati wal-arda haneefan wa maa ana minal-mushrikeen. Inna salaatee wa nusukee wa mahyaaya wa mamaatee lillaahi Rabbil-'aalameen, laa shareeka lahoo wa bizaalika umirtu wa ana minal-muslimeen. Allaahumma antal-Maliku laa ilaaha illaa ant, anta Rabbee wa ana 'abduk, zalamtu nafsee wa'taraftu bizanbee faghfir lee zunoobee jamee'an innahoo laa yaghfiruz- zunooba illaa ant. Wahdinee li-ahsanil-akhlaaqi laa","tar":"Maine apna rukh us zaat ki taraf kar liya jis ne aasmaan aur zameen banaye, sab se hat kar, aur main mushrikon mein se nahin hoon. Meri namaz, meri qurbani, meri zindagi aur meri maut sab Allah ke liye hain jo saare jahanon ka Rab hai. Uska koi shareek nahin, mujhe isi ka hukm diya gaya hai aur main Muslimon mein se hoon. Aye Allah! Tu hi badshah hai, tere siwa koi maabood nahin. Tu mera Rab hai aur main tera banda hoon. Maine apni jaan par zulm kiya aur apne gunah ka iqraar kiya, pas mere saare gunah bakhsh de, beshak tere siwa koi gunah bakhsh nahin sakta. Mujhe behtareen akhlaaq ki hidayat de, tere siwa koi us ki hidayat nahin de sakta, aur mujh se buraiyan door kar de, tere siwa koi in ko door nahin kar sakta. Main haazir hoon aur teri khidmat mein hoon, saari bhalai tere haathon mein hai aur burai teri taraf mansoob nahin ki jaati. Main tere saath hoon aur teri hi taraf hoon, tu barkat wala aur buland hai, main tujh se bakhshish maangta hoon aur teri","hi":"Maine apna rukh us zaat ki taraf kar liya jis ne aasmaan aur zameen banaye, sab se hat kar, aur main mushrikon (shirk karne walon) mein se nahin hoon. Meri namaz, meri qurbani, meri zindagi aur meri maut sab Allah ke liye hain jo saare jahanon ka Rab hai. Uska koi shareek nahin, mujhe isi ka hukm diya gaya hai aur main Muslimon mein se hoon. Ae Allah! Tu hi badshah hai, tere siwa koi ma'bood (ibadat ke laayak) nahin. Tu mera Rab hai aur main tera banda hoon. Maine apni jaan par zulm kiya aur apne gunah ka iqraar kiya, pas mere saare gunah maaf kar de, beshak tere siwa koi gunah maaf nahin kar sakta. Mujhe behtareen akhlaaq ki hidayat de, tere siwa koi us ki hidayat nahin de sakta, aur mujh se buraiyan door kar de, tere siwa koi in ko door nahin kar sakta. Main haazir hoon aur teri khidmat mein hoon, saari bhalai tere haathon mein hai aur burai teri taraf mansoob nahin ki jaati. Main tere saath hoon aur teri hi taraf hoon, tu barkat wala aur buland hai, main tujh se maafi maangta hoon aur teri","pg":87,"i":"d133","in":["Takbeer ke baad Nabi ﷺ yeh dua bhi padhte the (khaas taur par nafl aur tahajjud mein):"]},{"t":"p","s":"yahdee li-ahsanihaa illaa ant, wasrif 'annee sayyi-ahaa laa yasrifu 'annee sayyi-ahaa illaa ant. Labbayka wa sa'dayk, wal-khayru kulluhoo fee yadayk, wash-sharru laysa ilayk, ana bika wa ilayk, tabaarakta wa ta'aalayt, astaghfiruka wa atoobu ilayk.","h":0},{"t":"p","s":"taraf tauba karta hoon.","h":0},{"t":"d","id":"d134","ti":"2. Namaz shuru karne ki chhoti dua (Sahih Muslim 601, Hazrat Abdullah ibn Umar RA)","pad":"Allaahu akbaru kabeeraa, walhamdu lillaahi katheeraa, wa subhaanallaahi bukratan wa aseelaa.","tar":"Allah bahut bada hai, Allah ke liye bahut taareef hai, aur Allah ki paaki bayan karta hoon subah aur shaam. Nabi ﷺ ne is dua ke baare mein farmaya ke mujhe is par taajjub hua, is ke liye aasman ke darwaze khol diye gaye.","hi":"Allah bahut bada hai, Allah ke liye bahut tareef hai, aur Allah ki paaki bayan karta hoon subah aur shaam. Nabi ﷺ ne is dua ke baare mein farmaya ke mujhe is par taajjub hua, is ke liye aasman ke darwaze khol diye gaye.","pg":88,"i":"d134"},{"t":"p","s":"3. Ruku se uthne ke baad ki ek aur dua (Sahih Muslim 600)","h":1},{"t":"p","s":"Ek sahabi ne ruku se uth kar yeh kaha to Nabi ﷺ ne farmaya ke maine 30 se zyada farishte dekhe jo is baat par jhapat rahe the ke kaun pehle likhe: Rabbanaa wa lakal-hamd, hamdan katheeran tayyiban mubaarakan feeh (tarjuma Hissa 15 mein hai).","h":0},{"t":"d","id":"d135","ti":"4. Aakhri Tashahhud ke baad ki aur duaein","pad":"Allaahumma haasibnee hisaaban yaseeraa.","tar":"Aye Allah! Mera hisaab aasan farma.","hi":"Ae Allah! Mera hisaab aasan kar.","pg":89,"i":"d135","in":["Aasan hisaab ki dua (Musnad Ahmad, Mustadrak Hakim)"]},{"t":"d","id":"d136","ti":"Ism-e-A'zam ke saath dua","pad":"Allaahumma innee as-aluka bi-annee ash-hadu annaka antallaahu laa ilaaha illaa antal-Ahadus- Samad, allazee lam yalid wa lam yoolad wa lam yakul-lahoo kufuwan ahad.","tar":"Aye Allah! Main tujh se maangta hoon is gawahi ke saath ke tu hi Allah hai, tere siwa koi maabood nahin, tu ek hai, be-niyaaz hai, jis ne na kisi ko jana na woh jana gaya aur koi us ke barabar nahin.","hi":"Ae Allah! Main tujh se maangta hoon is gawahi ke saath ke tu hi Allah hai, tere siwa koi ma'bood (ibadat ke laayak) nahin, tu ek hai, be-parwah hai, jis ne na kisi ko jana na woh jana gaya aur koi us ke barabar nahin.","pg":89,"i":"d136","in":["Ism-e-A'zam ke saath dua (Abu Dawud 1493, Tirmidhi 3475) Ek sahabi ne Tashahhud mein yeh dua ki to Nabi ne farmaya: us ne Allah se us ke us naam ke saath maanga jis ke saath maanga jaaye to woh ata karta hai aur dua kiya jaaye to qubool karta hai:"]},{"t":"p","s":"5. Tashahhud mein dusre alfaaz (Sahih Muslim 403, Hazrat Abdullah ibn Abbas RA)","h":1},{"t":"p","s":"Nabi ﷺ se Tashahhud ke kuchh aur alfaaz bhi sabit hain, jaise (At-tahiyyaatul-mubaarakaatus- salawaatut-tayyibaatu lillaah). Baqi hissa wahi hai jo Hissa 5 mein hai.","h":0}]},{"n":20,"t":"Farz namaz ke baad ki duaein (ek nazar mein)","b":[{"t":"p","s":"Poori tafseel Hissa 8 aur Hissa 13 mein hai. Yeh sirf yaad rakhne ki fehrist hai.","h":0},{"t":"p","s":"1. Astaghfirullaah (3 baar)","h":0},{"t":"p","s":"2. Allaahumma antas-salaam (1 baar)","h":0},{"t":"p","s":"3. Rabbi qinee 'azaabaka (1 baar)","h":0},{"t":"p","s":"4. Subhaanaka Allaahumma... ya Laa ilaaha illallaah wahdahoo... (Hissa 13 ke mutabiq)","h":0},{"t":"p","s":"5. Ayat-ul-Kursi (1 baar)","h":0},{"t":"p","s":"6. Muawwizaat (Ikhlaas, Falaq, Naas)","h":0},{"t":"p","s":"7. Tasbeehaat: Subhaanallaah (33), Alhamdulillaah (33), Allaahu Akbar (33 ya 34), phir Laa ilaaha illallaahu wahdahoo... (1 baar)","h":0},{"t":"p","s":"8. Allaahumma a'innee 'alaa zikrika wa shukrika wa husni 'ibaadatik (har namaz ke baad, Hazrat Muaz RA ko Nabi ﷺ ki wasiyat)","h":0},{"t":"p","s":"9. Rabbanaa aatinaa fid-dunyaa hasanatan... (Nabi ﷺ ki sab se zyada ki jaane wali dua) 10. Allaahumma innee a'oozu bika minal-jubn... (Hissa 13) 11. Allaahummagh-fir lee maa qaddamtu... (Hissa 13)","h":0},{"t":"p","s":"12. Fajr aur Maghrib ke baad: 10 baar Laa ilaaha illallaahu wahdahoo... yuhyee wa yumeet aur 7 baar Allaahumma ajirnee minan-naar 13. Sirf Fajr ke baad: Allaahumma innee as-aluka 'ilman naafi'an... 14. Witr ke baad: Subhaanal-Malikil-Quddoos (3 baar)","h":0}]},{"n":21,"t":"Quran ki baaqi \"Rabbana\" wali duaein","b":[{"t":"p","s":"— kisne ki aur kab padhein","h":1},{"t":"p","s":"Jo \"Rabbana\" wali duaein Hissa 17 aur 18 mein aa chuki hain wo yahan dobara nahin hain. Har dua ke saath likha hai ke kisne ki (nabi, ya imaan wale, ya koi aur) aur kab padhein . Quran ki duaein kisi bhi waqt padhi ja sakti hain; \"kab padhein\" mein maine dua ke mafhoom ke hisaab se mauqa likha hai, jahan khaas hadees mein waqt aaya hai wahan alag likh diya hai.","h":0},{"t":"d","id":"d137","ti":"1. Nabi banane ki dua — Hazrat Ibrahim aur Ismail (Al- Baqarah 2:129)","pad":"Rabbanaa wab'ath feehim rasoolan minhum yatloo 'alayhim aayaatika wa yu'allimuhumul- kitaaba wal-hikmata wa yuzakkeehim, innaka antal-'Azeezul-Hakeem.","tar":"Aye hamare Rab! In mein inhi mein se ek rasool bhej jo inhein teri ayaat padh kar sunaye, kitaab aur hikmat sikhaye aur inhein paak kare, beshak tu zabardast, hikmat wala hai. Kab padhein: Deen ki ta'leem aur aulaad ki tarbiyat ke liye, aur Nabi ﷺ ke aane ki shukr-guzari mein.","hi":"Ae hamare Rab! In mein inhi mein se ek rasool bhej jo inhein teri ayaat padh kar sunaye, kitaab aur hikmat sikhaye aur inhein paak kare, beshak tu zabardast, hikmat wala hai. Kab padhein: Deen ki ta'leem aur aulaad ki tarbiyat ke liye, aur Nabi ﷺ ke aane ki shukr-guzari mein.","pg":91,"i":"d137"},{"t":"d","id":"d138","ti":"2. Hajj-o-Umrah ke shehar ke liye — Hazrat Ibrahim (Ibrahim 14:37)","pad":"Rabbanaa innee askantu min zurriyyatee biwaadin ghayri zee zar'in 'inda baytikal-muharram, Rabbanaa liyuqeemus-salaata faj'al af'idatan minan-naasi tahwee ilayhim warzuqhum minath-thamaraati la'allahum yashkuroon.","tar":"Aye hamare Rab! Maine apni aulaad ko ek be-kheti ki wadi mein tere muhtaram ghar ke paas basa diya hai. Aye hamare Rab! Taake woh namaz qaayam karein, pas logon ke dil in ki taraf maail kar de aur inhein phalon ka rizq de, shayad woh shukr karein.","hi":"Ae hamare Rab! Maine apni aulaad ko ek be-kheti ki wadi mein tere muhtaram ghar ke paas basa diya hai. Ae hamare Rab! Taake woh namaz qaayam karein, pas logon ke dil in ki taraf maail kar de aur inhein phalon ka rizq de, shayad woh shukr karein.","pg":92,"i":"d138","no":"Kab padhein: Rizq ki tangi mein aur ghar-aulaad ki hifaazat aur imaan ke liye."},{"t":"d","id":"d139","ti":"3. Dilon ka haal jaanne wala — Hazrat Ibrahim (Ibrahim 14:38)","pad":"Rabbanaa innaka ta'lamu maa nukhfee wa maa nu'lin, wa maa yakhfaa 'alallaahi min shay'in fil- ardi wa laa fis-samaa'.","tar":"Aye hamare Rab! Tu jaanta hai jo hum chhupate hain aur jo zaahir karte hain, aur Allah se zameen aur aasman mein koi cheez chhupi nahin.","hi":"Ae hamare Rab! Tu jaanta hai jo hum chhupate hain aur jo zaahir karte hain, aur Allah se zameen aur aasman mein koi cheez chhupi nahin.","pg":93,"i":"d139","no":"Kab padhein: Jab dil ki baat Allah ke saamne rakhni ho, aur ikhlaas ke liye."},{"t":"d","id":"d140","ti":"4. Fitne ka zariya na banna — Hazrat Ibrahim aur unke saathi (Al-Mumtahina 60:5)","pad":"Rabbanaa laa taj'alnaa fitnatan lillazeena kafaroo waghfir lanaa Rabbanaa, innaka antal-'Azeezul- Hakeem.","tar":"Aye hamare Rab! Hamein kaafiron ke liye fitna na bana aur hamein bakhsh de, aye hamare Rab! Beshak tu zabardast, hikmat wala hai.","hi":"Ae hamare Rab! Humein kaafiron ke liye fitna na bana aur humein maaf kar de, ae hamare Rab! Beshak tu zabardast, hikmat wala hai.","pg":94,"i":"d140","no":"Kab padhein: Jab kisi mushkil mahaul mein deen par saabit rehna ho."},{"t":"d","id":"d141","ti":"5. Zalimon ka saath na ho — A'raaf waale (Al-A'raaf 7:47)","pad":"Rabbanaa laa taj'alnaa ma'al-qawmiz-zaalimeen.","tar":"Aye hamare Rab! Hamein zalim logon ke saath na kar.","hi":"Ae hamare Rab! Humein zalim logon ke saath na kar.","pg":94,"i":"d141","no":"Kab padhein: Burai ke mahaul se bachne ke liye."},{"t":"d","id":"d142","ti":"6. Sabr aur islam ki haalat mein maut — Firaun ke jaadugar (Al-A'raaf 7:126)","pad":"Rabbanaa afrigh 'alaynaa sabran wa tawaﬀanaa muslimeen.","tar":"Aye hamare Rab! Hum par sabr undel de aur hamein islam ki haalat mein maut de.","hi":"Ae hamare Rab! Hum par sabr undel de aur humein islam ki haalat mein maut de.","pg":94,"i":"d142","in":["Jab Firaun ne unhein dhamkaya to imaan laane ke baad unhon ne yeh kaha:"],"no":"Kab padhein: Zulm ya dabaao ke waqt, aur apne imaan par khaatima ke liye."},{"t":"d","id":"d143","ti":"7. Zalimon ka fitna na banna — Hazrat Moosa ki qaum (Yoonus 10:85 aur 86)","pad":"Rabbanaa laa taj'alnaa fitnatan lil-qawmiz-zaalimeen, wa najjinaa bi-rahmatika minal-qawmil- kaafireen.","tar":"Aye hamare Rab! Hamein zalim logon ke liye fitna na bana, aur apni rehmat se hamein kaafir qaum se najaat de.","hi":"Ae hamare Rab! Humein zalim logon ke liye fitna na bana, aur apni rehmat se humein kaafir qaum se najaat de.","pg":95,"i":"d143","no":"Kab padhein: Zulm se najaat aur bure logon ki zyadti se bachne ke liye."},{"t":"d","id":"d144","ti":"8. Gunahon aur had se badhne ki muaafi — Allah waale (Aal- e-Imran 3:147)","pad":"Rabbanagh-fir lanaa zunoobanaa wa israafanaa fee amrinaa wa sabbit aqdaamanaa wansurnaa 'alal-qawmil-kaafireen.","tar":"Aye hamare Rab! Hamare gunah aur hamare kaam mein hamari had se badhne ko bakhsh de, hamare qadam jamaa de aur kaafir qaum ke muqable mein hamari madad farma.","hi":"Ae hamare Rab! Hamare gunah aur hamare kaam mein hamari had se badhne ko maaf kar de, hamare qadam jamaa de aur kaafir qaum ke muqable mein hamari madad kar.","pg":96,"i":"d144","in":["In pehle ke nabiyon ke saathiyon ne jang ke waqt yeh dua ki thi:"],"no":"Kab padhein: Imtihaan aur mushkil ke waqt, aur apni zyadtiyon par tauba ke liye."},{"t":"d","id":"d145","ti":"9. Hazrat Isa ke saathi (Aal-e-Imran 3:53)","pad":"Rabbanaa aamannaa bimaa anzalta wattaba'nar-rasoola faktubnaa ma'ash-shaahideen.","tar":"Aye hamare Rab! Hum us par imaan laaye jo tu ne utaara aur hum ne rasool ki pairwi ki, pas hamein gawahi dene walon ke saath likh le. Kab padhein: Imaan par saabit rehne aur Nabi ki pairwi ki dua ke taur par.","hi":"Ae hamare Rab! Hum us par imaan laaye jo tu ne utaara aur hum ne rasool ki pairwi ki, pas humein gawahi dene walon ke saath likh le. Kab padhein: Imaan par saabit rehne aur Nabi ki pairwi ki dua ke taur par.","pg":96,"i":"d145"},{"t":"d","id":"d146","ti":"10. Hazrat Isa ki dua — dastarkhwan ke liye (Al-Maaida 5:114)","pad":"Allaahumma Rabbanaa anzil 'alaynaa maa'idatan minas-samaa'i takoonu lanaa 'eedan li- awwalinaa wa aakhirinaa wa aayatan minka, warzuqnaa wa anta khayrur-raaziqeen.","tar":"Aye Allah, hamare Rab! Hum par aasman se khaane ka dastarkhwan utaar jo hamare aglon aur pichhlon ke liye eid ho aur teri taraf se nishaani ho, aur hamein rizq de, tu sab se behtar rizq dene wala hai.","hi":"Ae Allah, hamare Rab! Hum par aasman se khaane ka dastarkhwan utaar jo hamare aglon aur pichhlon ke liye eid ho aur teri taraf se nishaani ho, aur humein rizq de, tu sab se behtar rizq dene wala hai.","pg":97,"i":"d146","no":"Kab padhein: Rizq ki tangi mein."},{"t":"d","id":"d147","ti":"11. Imaan waalon ki dua (Al-Maaida 5:83)","pad":"Rabbanaa aamannaa faktubnaa ma'ash-shaahideen.","tar":"Aye hamare Rab! Hum imaan laaye, pas hamein gawahi dene walon ke saath likh le.","hi":"Ae hamare Rab! Hum imaan laaye, pas humein gawahi dene walon ke saath likh le.","pg":97,"i":"d147","no":"Kab padhein: Haq qubool karne ke baad shukr aur saabit-qadmi ki dua ke taur par."},{"t":"d","id":"d148","ti":"12. Zameen aasman par ghaur karne walon ki dua (Aal-e- Imran 3:191)","pad":"Rabbanaa maa khalaqta haazaa baatilan, subhaanaka faqinaa 'azaaban-naar.","tar":"Aye hamare Rab! Tu ne yeh sab bekaar paida nahin kiya, tu paak hai, pas hamein aag ke azaab se bacha. Kab padhein: Raat ko uthne ke baad, aasman aur kaayenaat par ghaur karte waqt. (Nabi raat ko in ayaat ko padha karte the.)","hi":"Ae hamare Rab! Tu ne yeh sab bekaar paida nahin kiya, tu paak hai, pas humein aag ke azaab se bacha. Kab padhein: Raat ko uthne ke baad, aasman aur kaayenaat par ghaur karte waqt. (Nabi raat ko in ayaat ko padha karte the.)","pg":98,"i":"d148"},{"t":"d","id":"d149","ti":"13. Jahannam ki ruswai se panaah (Aal-e-Imran 3:192)","pad":"Rabbanaa innaka man tudkhilin-naara faqad akhzaytah, wa maa lizzaalimeena min ansaar.","tar":"Aye hamare Rab! Jise tu aag mein daal de use tu ne ruswa kar diya, aur zalimon ka koi madadgaar nahin.","hi":"Ae hamare Rab! Jise tu aag mein daal de use tu ne ruswa kar diya, aur zalimon ka koi madadgaar nahin.","pg":98,"i":"d149","no":"Kab padhein: Aakhirat ki fikr aur jahannam se panaah ke liye."},{"t":"d","id":"d150","ti":"14. Nek logon ke saath maut (Aal-e-Imran 3:193)","pad":"Rabbanaa innanaa sami'naa munaadiyan yunaadee lil-eemaani an aaminoo bi- Rabbikum fa- aamannaa. Rabbanaa faghfir lanaa zunoobanaa wa kaﬃr 'annaa sayyi-aatinaa wa tawaﬀanaa ma'al-abraar.","tar":"Aye hamare Rab! Hum ne ek pukarne waale ko suna jo imaan ki taraf bulata tha ke apne Rab par imaan lao, pas hum imaan laaye. Aye hamare Rab! Hamare gunah bakhsh de, hamari buraiyan hum se door kar de aur hamein nek logon ke saath maut de.","hi":"Ae hamare Rab! Hum ne ek pukarne waale ko suna jo imaan ki taraf bulata tha ke apne Rab par imaan lao, pas hum imaan laaye. Ae hamare Rab! Hamare gunah maaf kar de, hamari buraiyan hum se door kar de aur humein nek logon ke saath maut de.","pg":99,"i":"d150","no":"Kab padhein: Tauba aur achhe khaatime ke liye."},{"t":"d","id":"d151","ti":"15. Wade ki yaaddihaani (Aal-e-Imran 3:194)","pad":"Rabbanaa wa aatinaa maa wa'attanaa 'alaa rusulika wa laa tukhzinaa yawmal-qiyaamah, innaka laa tukhliful-mee'aad.","tar":"Aye hamare Rab! Hamein woh ata farma jis ka tu ne apne rasoolon ke zariye wada kiya aur Qayamat ke din hamein ruswa na kar, beshak tu wada khilaafi nahin karta.","hi":"Ae hamare Rab! Humein woh ata kar jis ka tu ne apne rasoolon ke zariye wada kiya aur Qayamat ke din humein ruswa na kar, beshak tu wada khilaafi nahin karta.","pg":100,"i":"d151","no":"Kab padhein: Qayamat ke din ki ruswai se bachne ke liye."},{"t":"d","id":"d152","ti":"16. Pichhle imaan waalon ke liye aur dil se keena nikalne ki dua (Al-Hashr 59:10)","pad":"Rabbanagh-fir lanaa wa li-ikhwaaninal-lazeena sabaqoonaa bil-eemaani wa laa taj'al fee quloobinaa ghillan lillazeena aamanoo, Rabbanaa innaka Ra'oofur-Raheem.","tar":"Aye hamare Rab! Hamein aur hamare un bhaaiyon ko bakhsh de jo imaan mein hum se pehle guzar gaye, aur hamare dilon mein imaan walon ke liye keena na rakh. Aye hamare Rab! Beshak tu bahut shafeeq, bahut reham karne wala hai.","hi":"Ae hamare Rab! Humein aur hamare un bhaaiyon ko maaf kar de jo imaan mein hum se pehle guzar gaye, aur hamare dilon mein imaan walon ke liye keena na rakh. Ae hamare Rab! Beshak tu bahut shafeeq, bahut reham karne wala hai.","pg":100,"i":"d152","in":["Yeh dua un logon ki hai jo Sahaba ke baad aaye:"],"no":"Kab padhein: Guzre hue Muslimon ke liye dua karte waqt aur dil ko kinay se saaf rakhne ke liye."},{"t":"d","id":"d153","ti":"17. Farishton ki dua imaan walon ke liye (Ghaafir 40:7)","pad":"Rabbanaa wasi'ta kulla shay'ir-rahmatan wa 'ilman faghfir lillazeena taaboo wattaba'oo sabeelaka wa qihim 'azaabal-jaheem.","tar":"Aye hamare Rab! Tu ne har cheez ko apni rehmat aur ilm se gher rakha hai, pas jin logon ne tauba ki aur tere raaste par chale unhein bakhsh de aur unhein jahannam ke azaab se bacha.","hi":"Ae hamare Rab! Tu ne har cheez ko apni rehmat aur ilm se gher rakha hai, pas jin logon ne tauba ki aur tere raaste par chale unhein maaf kar de aur unhein jahannam ke azaab se bacha.","pg":101,"i":"d153","in":["Arsh ko uthane waale farishte yeh dua karte hain:"],"no":"Kab padhein: Doosre Muslimon ke liye dua karte waqt."},{"t":"d","id":"d154","ti":"18. Imaan waale (Al-Mu'minoon 23:109)","pad":"Rabbanaa aamannaa faghfir lanaa warhamnaa wa anta khayrur-raahimeen.","tar":"Aye hamare Rab! Hum imaan laaye, pas hamein bakhsh de aur hum par reham farma, aur tu sab se behtar reham karne wala hai.","hi":"Ae hamare Rab! Hum imaan laaye, pas humein maaf kar de aur hum par reham kar, aur tu sab se behtar reham karne wala hai.","pg":102,"i":"d154","no":"Kab padhein: Har waqt, khaas taur par tauba ke baad."}]},{"n":22,"t":"Kab kaun si dua padhein — ek nazar mein","b":[{"t":"i","i":"t08"}]}];
